          );
        })}
      </div>

      {showSummary && (
        <div className="mt-6 transition-all duration-300 ease-out">
          <div className="bg-white rounded-2xl border border-gray-200 shadow-lg shadow-gray-200/50 overflow-hidden">
            <div className="p-5">
