import React, { useState } from 'react';
import { Search, Heart, Brain, Dna, Activity, User, Shield, Droplets, Flame, ArrowRight } from 'lucide-react';

const HEALTH_CONCERNS = [
  { icon: <Flame className="w-7 h-7" />, label: 'Diabetes', desc: 'Blood sugar & HbA1c', color: 'from-red-500 to-orange-500', bg: 'bg-red-50', text: 'text-red-600' },
  { icon: <Heart className="w-7 h-7" />, label: 'Heart Health', desc: 'Lipid profile & cardiac risk', color: 'from-rose-500 to-pink-500', bg: 'bg-rose-50', text: 'text-rose-600' },
  { icon: <Brain className="w-7 h-7" />, label: 'Thyroid Care', desc: 'T3, T4, TSH function', color: 'from-purple-500 to-indigo-500', bg: 'bg-purple-50', text: 'text-purple-600' },
  { icon: <Dna className="w-7 h-7" />, label: 'Kidney Function', desc: 'KFT, creatinine, urea', color: 'from-blue-500 to-cyan-500', bg: 'bg-blue-50', text: 'text-blue-600' },
  { icon: <Activity className="w-7 h-7" />, label: 'Liver Care', desc: 'LFT, bilirubin, enzymes', color: 'from-emerald-500 to-teal-500', bg: 'bg-emerald-50', text: 'text-emerald-600' },
  { icon: <User className="w-7 h-7" />, label: 'Senior Citizen', desc: 'Full body screening 60+', color: 'from-amber-500 to-yellow-500', bg: 'bg-amber-50', text: 'text-amber-600' },
  { icon: <Shield className="w-7 h-7" />, label: 'Women Wellness', desc: 'ANC profile & hormones', color: 'from-pink-500 to-rose-500', bg: 'bg-pink-50', text: 'text-pink-600' },
  { icon: <Droplets className="w-7 h-7" />, label: 'Routine Checkup', desc: 'CBC, urine, baseline', color: 'from-sky-500 to-blue-500', bg: 'bg-sky-50', text: 'text-sky-600' },
];

const PREDICTIVE_TESTS = [
  { name: 'Complete Blood Count (CBC)', code: 'CBC', price: 200, category: 'Hematology' },
  { name: 'Thyroid Function Test (T3, T4, TSH)', code: 'TFT', price: 450, category: 'Immunology' },
  { name: 'Lipid Profile', code: 'LIPID', price: 650, category: 'Biochemistry' },
  { name: 'Liver Function Test (LFT)', code: 'LFT', price: 500, category: 'Biochemistry' },
  { name: 'Kidney Function Test (KFT)', code: 'KFT', price: 500, category: 'Biochemistry' },
  { name: 'HbA1c (Glycosylated Haemoglobin)', code: 'HBA1C', price: 400, category: 'Biochemistry' },
];

const HealthConcernGrid = ({ scrollToSection, t, language }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);

  const filteredPredictions = PREDICTIVE_TESTS.filter(test =>
    test.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    test.code.toLowerCase().includes(searchQuery.toLowerCase()) ||
    test.category.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <section className="py-20 bg-gradient-to-b from-white to-slate-50 px-4 sm:px-6 lg:px-8 relative overflow-hidden" id="health-concerns">
      <div className="absolute top-0 left-1/4 w-96 h-96 bg-secondary-pale/40 rounded-full blur-[120px] pointer-events-none"></div>
      <div className="max-w-7xl mx-auto relative z-10">
        <div className="text-center mb-12">
          <span className="text-xs font-black tracking-widest text-secondary uppercase bg-secondary-pale px-4 py-1.5 rounded-full">Smart Discovery</span>
          <h2 className="text-4xl font-heading text-primary font-black mt-4">Find the Right Test for You</h2>
          <p className="text-slate-500 mt-2 max-w-2xl mx-auto font-medium">Search from 250+ diagnostic tests or browse by health concern</p>
          <div className="w-16 h-1 bg-cta mx-auto mt-4 rounded-full"></div>
        </div>

        {/* Predictive Search Bar */}
        <div className="max-w-2xl mx-auto mb-12 relative">
          <div className="relative">
            <Search className="absolute left-5 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => { setSearchQuery(e.target.value); setShowSuggestions(true); }}
              onFocus={() => setShowSuggestions(true)}
              onBlur={() => setTimeout(() => setShowSuggestions(false), 200)}
              placeholder="Search tests, panels, or health conditions..."
              className="w-full pl-14 pr-6 py-4 bg-white border-2 border-slate-200 focus:border-secondary rounded-2xl text-base font-semibold outline-none transition-all shadow-lg shadow-slate-100/50"
            />
            <button className="absolute right-3 top-1/2 -translate-y-1/2 bg-gradient-to-r from-secondary to-secondary-light text-white px-5 py-2 rounded-xl text-sm font-bold shadow-md hover:-translate-y-0.5 transition-all">Search</button>
          </div>

          {/* Autocomplete Suggestions */}
          {showSuggestions && searchQuery && filteredPredictions.length > 0 && (
            <div className="absolute top-full mt-2 left-0 right-0 bg-white rounded-2xl shadow-xl border border-slate-100 overflow-hidden z-20 animate-slide-down">
              {filteredPredictions.map((test, i) => (
                <button key={i} onMouseDown={() => { setSearchQuery(test.name); scrollToSection('services'); }} className="w-full flex items-center justify-between px-5 py-3.5 hover:bg-secondary-pale/30 transition-colors text-left border-b border-slate-50 last:border-0">
                  <div>
                    <p className="font-bold text-slate-800 text-sm">{test.name}</p>
                    <p className="text-xs text-slate-400 font-medium mt-0.5">{test.category} • {test.code}</p>
                  </div>
                  <span className="text-secondary font-black text-sm">₹{test.price}</span>
                </button>
              ))}
            </div>
          )}
        </div>

        {/* Health Concern Grid */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 md:gap-6">
          {HEALTH_CONCERNS.map((concern, i) => (
            <button
              key={i}
              onClick={() => scrollToSection('services')}
              className="group bg-white rounded-2xl p-5 md:p-6 border border-slate-100 hover:border-secondary/20 shadow-sm hover:shadow-xl transition-all duration-300 hover:-translate-y-1.5 text-center relative overflow-hidden"
            >
              <div className={`w-14 h-14 rounded-2xl ${concern.bg} flex items-center justify-center mx-auto mb-3.5 group-hover:scale-110 transition-transform duration-300 ${concern.text}`}>
                {concern.icon}
              </div>
              <h3 className="font-black text-slate-800 text-sm md:text-base mb-1">{concern.label}</h3>
              <p className="text-xs text-slate-500 font-medium">{concern.desc}</p>
              <div className={`absolute bottom-0 left-0 right-0 h-1 bg-gradient-to-r ${concern.color} scale-x-0 group-hover:scale-x-100 transition-transform duration-300 origin-left`}></div>
            </button>
          ))}
        </div>

        <div className="text-center mt-10">
          <button onClick={() => scrollToSection('services')} className="inline-flex items-center gap-2 text-sm font-bold text-secondary hover:text-secondary-light transition-colors">
            <span>View all 250+ tests</span>
            <ArrowRight size={16} />
          </button>
        </div>
      </div>
    </section>
  );
};

export default HealthConcernGrid;

import React, { useContext, useState } from 'react';
import { NavLink, useNavigate, useLocation } from 'react-router-dom';
import { AuthContext } from '../context/AuthContext';
import { LogOut, Search, MapPin, Phone, Mail, Menu, X } from 'lucide-react';
import Logo from './Logo';
import WhatsAppIcon from './WhatsAppIcon';

const Layout = ({ children }) => {
  const { user, logout } = useContext(AuthContext);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [newBookingAlert, setNewBookingAlert] = useState(null);
  const navigate = useNavigate();
  const location = useLocation();
  const knownAppointmentIds = React.useRef(new Set());

  const playChime = () => {
    try {
      const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      const playNote = (frequency, startTime, duration) => {
        const osc = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(frequency, startTime);
        gain.gain.setValueAtTime(0.2, startTime);
        gain.gain.exponentialRampToValueAtTime(0.0001, startTime + duration);
        osc.connect(gain);
        gain.connect(audioCtx.destination);
        osc.start(startTime);
        osc.stop(startTime + duration);
      };
      playNote(523.25, audioCtx.currentTime, 0.4); // C5
      playNote(659.25, audioCtx.currentTime + 0.15, 0.5); // E5
    } catch (e) {
      console.error('Failed to play chime:', e);
    }
  };

  React.useEffect(() => {
    if (!user || user.userType === 'PATIENT') return;

    const headers = { 'Authorization': `Bearer ${user.accessToken}` };
    
    // Initial fetch to load existing appointments
    fetch('/api/appointments', { headers })
      .then(r => r.json())
      .then(data => {
        if (Array.isArray(data)) {
          knownAppointmentIds.current = new Set(data.map(a => a.id));
        }
      })
      .catch(console.error);

    // Setup short polling interval
    const interval = setInterval(() => {
      fetch('/api/appointments', { headers })
        .then(r => r.json())
        .then(data => {
          if (Array.isArray(data)) {
            let foundNew = false;
            data.forEach(apt => {
              if (!knownAppointmentIds.current.has(apt.id)) {
                knownAppointmentIds.current.add(apt.id);
                // Trigger alert if status is SCHEDULED
                if (apt.status === 'SCHEDULED') {
                  foundNew = true;
                  setNewBookingAlert({
                    id: apt.id,
                    name: apt.patient?.fullName || 'New Patient',
                    date: apt.date,
                    time: apt.time
                  });
                }
              }
            });
            if (foundNew) {
              playChime();
            }
          }
        })
        .catch(console.error);
    }, 15000); // Check every 15 seconds

    return () => clearInterval(interval);
  }, [user]);

  // Don't render layout elements on the print route
  if (location.pathname.includes('/print/')) {
    return <div className="print-only bg-white">{children}</div>;
  }

  let links = [];
  if (user?.userType === 'PATIENT') {
    links = [
      { name: 'Dashboard', path: '/dashboard' },
      { name: 'My Reports', path: '/reports' }
    ];
  } else if (user?.userType === 'DOCTOR') {
    links = [
      { name: 'Dashboard', path: '/doctor/dashboard' },
      { name: 'My Patients', path: '/reports' }
    ];
  } else {
    links = [
      { name: 'Dashboard', path: '/dashboard' },
      { name: 'Patients', path: '/patients' },
      { name: 'Doctors', path: '/doctors' },
      { name: 'Dr. Analytics', path: '/doctors/analytics' },
      { name: 'Tests', path: '/tests' },
      { name: 'Packages', path: '/dashboard/packages' },
      { name: 'Reports', path: '/reports' },
      { name: 'Billing', path: '/billing' },
      { name: 'Appointments', path: '/appointments' },
      { name: 'Collections', path: '/dashboard/collections' },
      { name: 'Inventory', path: '/inventory' },
      { name: 'Staff', path: '/staff' },
      { name: 'Activity Log', path: '/activity-log' },
      { name: 'Settings', path: '/settings' },
    ];
  }


  return (
    <div className="flex flex-col min-h-screen bg-gray-50 font-sans">
      {/* Top utility bar */}
      <div className="bg-[#00488d] text-white text-xs py-1 px-4 hidden md:block">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <div className="flex items-center space-x-6">
            <span className="flex items-center"><MapPin className="w-3 h-3 mr-1" /> Datawali Road, Near Aara Machine, Hayat Nagar</span>
          </div>
          <div className="flex items-center space-x-4">
            <span className="flex items-center"><Phone className="w-3 h-3 mr-1" /> 6396786939 / 6397240575</span>
            <span>|</span>
            <span className="font-semibold">{user?.name} ({user?.role})</span>
          </div>
        </div>
      </div>

      {/* Main Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-50 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-20 gap-4">
            {/* Logo */}
            <div className="flex-shrink-0 flex items-center cursor-pointer" onClick={() => navigate('/dashboard')}>
              <Logo className="w-10 h-10 sm:w-12 sm:h-12 mr-2" />
              <div className="text-[#00488d] font-extrabold text-lg sm:text-xl lg:text-2xl tracking-tight flex items-center whitespace-nowrap">
                SANA PATHOLOGY LAB
              </div>
            </div>

            {/* Global Search */}
            <div className="hidden lg:flex items-center flex-1 max-w-sm">
              <div className="relative w-full">
                <input 
                  type="text" 
                  placeholder="Global Search..." 
                  className="w-full pl-10 pr-4 py-2 bg-gray-50 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-[#00488d] focus:border-transparent transition-all"
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' && e.target.value) {
                      navigate('/patients?search=' + encodeURIComponent(e.target.value));
                    }
                  }}
                />
                <Search className="w-4 h-4 text-gray-400 absolute left-3 top-2.5" />
              </div>
            </div>

            {/* Right side actions (desktop) */}
            <div className="hidden lg:flex items-center space-x-3 flex-shrink-0">
              <button 
                onClick={logout}
                className="bg-[#ffb800] hover:bg-yellow-500 text-gray-900 px-4 py-2 rounded font-bold text-sm transition-colors shadow-sm whitespace-nowrap"
              >
                Logout
              </button>
            </div>

            {/* Mobile menu button */}
            <div className="lg:hidden flex items-center">
              <button 
                onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
                className="text-[#00488d] p-2"
                aria-label="Toggle menu"
              >
                {mobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
              </button>
            </div>
          </div>
        </div>

        {/* Desktop / Tablet Navigation - own row, horizontally scrollable on small screens */}
        <nav className="hidden lg:block bg-white border-t border-gray-100">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex items-center justify-center gap-1 overflow-x-auto whitespace-nowrap nav-scroll">
              {links.map((link) => (
                <NavLink
                  key={link.name}
                  to={link.path}
                  className={({ isActive }) =>
                    `px-3 xl:px-4 py-3 text-xs xl:text-sm font-bold uppercase tracking-wide transition-colors nav-link flex-shrink-0 ${
                      isActive ? 'text-[#00488d] active' : 'text-gray-600 hover:text-[#00488d]'
                    }`
                  }
                >
                  {link.name}
                </NavLink>
              ))}
            </div>
          </div>
        </nav>

        {/* Mobile Menu */}
        {mobileMenuOpen && (
          <div className="lg:hidden bg-white border-b border-gray-200">
            <div className="px-2 pt-2 pb-3 space-y-1 sm:px-3">
              <div className="lg:hidden px-3 py-2">
                <div className="relative">
                  <input 
                    type="text" 
                    placeholder="Global Search..." 
                    className="w-full pl-10 pr-4 py-2 bg-gray-50 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-[#00488d] focus:border-transparent transition-all"
                    onKeyDown={(e) => {
                      if (e.key === 'Enter' && e.target.value) {
                        navigate('/patients?search=' + encodeURIComponent(e.target.value));
                        setMobileMenuOpen(false);
                      }
                    }}
                  />
                  <Search className="w-4 h-4 text-gray-400 absolute left-3 top-2.5" />
                </div>
              </div>
              {links.map((link) => (
                <NavLink
                  key={link.name}
                  to={link.path}
                  onClick={() => setMobileMenuOpen(false)}
                  className={({ isActive }) =>
                    `block px-3 py-2 rounded-md text-base font-bold uppercase ${
                      isActive ? 'bg-[#00488d] text-white' : 'text-gray-600 hover:bg-gray-50'
                    }`
                  }
                >
                  {link.name}
                </NavLink>
              ))}
              <button 
                onClick={logout}
                className="w-full text-left mt-4 bg-[#ffb800] text-gray-900 px-3 py-2 rounded-md text-base font-bold uppercase"
              >
                Logout
              </button>
            </div>
          </div>
        )}
      </header>

      {/* Main Content */}
      <main className="flex-1 w-full max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {children}
      </main>

      {/* Footer */}
      <footer className="bg-[#00488d] text-white py-6 mt-auto">
        <div className="max-w-7xl mx-auto px-4 text-center text-sm">
          <p>© {new Date().getFullYear()} Sana Pathology Lab. All Rights Reserved.</p>
        </div>
      </footer>

      {/* Floating live booking alert */}
      {newBookingAlert && (
        <div className="fixed bottom-6 right-6 z-50 bg-[#00488d] text-white p-5 rounded-2xl shadow-2xl border border-white/10 max-w-sm w-full animate-fade-in flex flex-col gap-3">
          <div className="flex justify-between items-start">
            <div className="flex items-center gap-2">
              <span className="w-2.5 h-2.5 bg-[#ffb800] rounded-full animate-ping"></span>
              <h4 className="font-extrabold text-sm uppercase tracking-wider text-[#ffb800]">New Booking Alert!</h4>
            </div>
            <button 
              onClick={() => setNewBookingAlert(null)}
              className="text-white/70 hover:text-white font-bold text-xs"
            >
              Close
            </button>
          </div>
          <div>
            <p className="font-black text-base">{newBookingAlert.name}</p>
            <p className="text-xs text-white/80 mt-1">
              Scheduled for {new Date(newBookingAlert.date).toLocaleDateString()} at {newBookingAlert.time}
            </p>
          </div>
          <button 
            onClick={() => {
              setNewBookingAlert(null);
              navigate('/appointments');
            }}
            className="w-full bg-[#ffb800] hover:bg-yellow-500 text-gray-900 font-bold text-xs py-2.5 rounded-lg transition-colors text-center"
          >
            View Appointments List
          </button>
        </div>
      )}

      {/* Floating WhatsApp Button */}
      <a 
        href="https://wa.me/916396786939?text=Hi%20Sana%20Pathology%2C%20I%20have%20a%20query%20about%20a%20booking%20or%20report"
        target="_blank"
        rel="noopener noreferrer"
        className="fixed bottom-6 right-6 z-50 bg-[#25D366] text-white p-3.5 rounded-full shadow-2xl hover:scale-110 active:scale-95 transition-transform flex items-center justify-center"
        title="Contact WhatsApp Support"
      >
        <WhatsAppIcon className="w-6 h-6" />
      </a>
    </div>
  );
};

export default Layout;

