        className="w-[85.6mm] h-[53.98mm] bg-white rounded-xl shadow-lg border border-gray-200 overflow-hidden relative flex flex-col font-sans"
        style={{ width: '340px', height: '214px' }} // Approx CR80 ID Card dimensions
      >
