              <AlertCircle className="w-4 h-4" />
              {isHindi
                ? `आप वर्तमान में "${subscription.planNameHi}" योजना पर हैं। ऊपर से अपग्रेड या डाउनग्रेड करें।`
                : `You are on the "${subscription.planName}" plan. Upgrade or downgrade above.`
              }
            </div>
          </div>
        )}

        <ComparisonTable />
      </div>
    </section>
  );
};

