                  <button onClick={() => { setOtpSent(false); setOtpValue(''); }} className="text-xs font-bold text-slate-500 hover:text-primary text-center w-full underline">Change ID / Resend OTP</button>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </>
  );
};

