source:
import React, { useState, useEffect, useContext } from 'react';
import Layout from '../components/Layout';
import { AuthContext } from '../context/AuthContext';
import { Search, IndianRupee, CreditCard, Receipt, TrendingUp, Wallet, QrCode, CheckCircle2, X, Tag, Percent, Pencil, Trash2 } from 'lucide-react';
import { QRCodeSVG } from 'qrcode.react';

const Billing = () => {
  const { user } = useContext(AuthContext);
  const [invoices, setInvoices] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isPaymentModalOpen, setIsPaymentModalOpen] = useState(false);
  const [selectedInvoice, setSelectedInvoice] = useState(null);
  const [paymentMethod, setPaymentMethod] = useState('CASH');
  const [isProcessing, setIsProcessing] = useState(false);

  // Discount state
  const [discountBy, setDiscountBy] = useState('');
  const [discountType, setDiscountType] = useState('PERCENT');
  const [discountValue, setDiscountValue] = useState('');
  const [isApplyingDiscount, setIsApplyingDiscount] = useState(false);
  const [discountApplied, setDiscountApplied] = useState(false);

  // Edit Invoice state
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [editInvoice, setEditInvoice] = useState(null);
  const [editFinalAmount, setEditFinalAmount] = useState('');
  const [editDiscount, setEditDiscount] = useState('');
  const [editPaymentStatus, setEditPaymentStatus] = useState('UNPAID');
  const [editPaymentMethod, setEditPaymentMethod] = useState('');
  const [isSavingEdit, setIsSavingEdit] = useState(false);

  // Bulk Selection State
  const [selectedInvoiceIds, setSelectedInvoiceIds] = useState([]);

  useEffect(() => { fetchInvoices(); }, []);

  const fetchInvoices = async () => {
    try {
      const res = await fetch('/api/invoices', {
        headers: { 'Authorization': `Bearer ${user?.token || user?.accessToken}` }
      });
      const data = await res.json();
      if (Array.isArray(data)) {
        setInvoices(data);
        setSelectedInvoiceIds([]);
      }
    } catch (err) { console.error(err); }
  };

  const handlePayClick = (inv) => {
    setSelectedInvoice(inv);
    setPaymentMethod('CASH');
    setDiscountBy('');
    setDiscountType('PERCENT');
    setDiscountValue('');
    setDiscountApplied(inv.discount > 0);
    setIsPaymentModalOpen(true);
  };

  const handleApplyDiscount = async () => {
    if (!discountValue || parseFloat(discountValue) <= 0) return;
    setIsApplyingDiscount(true);
    try {
      const res = await fetch(`/api/invoices/${selectedInvoice.id}/discount`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${user?.token || user?.accessToken}` },
        body: JSON.stringify({ discountType, discountValue: parseFloat(discountValue), discountBy })
      });
      if (res.ok) {
        const updated = await res.json();
        setSelectedInvoice(prev => ({ ...prev, ...updated }));
        setDiscountApplied(true);
        setInvoices(prev => prev.map(inv => inv.id === updated.id ? { ...inv, ...updated } : inv));
      }
    } catch (err) { console.error(err); }
    finally { setIsApplyingDiscount(false); }
  };

  const handleRemoveDiscount = async () => {
    setIsApplyingDiscount(true);
    try {
      const res = await fetch(`/api/invoices/${selectedInvoice.id}/discount`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${user?.token || user?.accessToken}` },
        body: JSON.stringify({ discountType: 'FIXED', discountValue: 0 })
      });
      if (res.ok) {
        const updated = await res.json();
        setSelectedInvoice(prev => ({ ...prev, ...updated }));
        setDiscountApplied(false);
        setDiscountValue('');
        setDiscountBy('');
      }
    } catch (err) { console.error(err); }
    finally { setIsApplyingDiscount(false); }
  };

  const handleProcessPayment = async () => {
    if (!selectedInvoice) return;
    setIsProcessing(true);
    try {
      const res = await fetch(`/api/invoices/${selectedInvoice.id}/pay`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${user?.token || user?.accessToken}` },
        body: JSON.stringify({ amount: selectedInvoice.finalAmount, paymentMethod })
      });
      if (res.ok) { setIsPaymentModalOpen(false); fetchInvoices(); }
      else alert('Payment failed to process');
    } catch (err) { console.error(err); }
    finally { setIsProcessing(false); }
  };

  const handleEditClick = (inv) => {
    setEditInvoice(inv);
    setEditFinalAmount(inv.finalAmount.toString());
    setEditDiscount(inv.discount.toString());
    setEditPaymentStatus(inv.paymentStatus || 'UNPAID');
    setEditPaymentMethod(inv.paymentMethod || '');
    setIsEditModalOpen(true);
  };

  const handleSaveEdit = async () => {
    if (!editInvoice) return;
    setIsSavingEdit(true);
    try {
      const res = await fetch(`/api/invoices/${editInvoice.id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${user?.token || user?.accessToken}`
        },
        body: JSON.stringify({
          finalAmount: parseFloat(editFinalAmount) || 0,
          discount: parseFloat(editDiscount) || 0,
          paymentStatus: editPaymentStatus,
          paymentMethod: editPaymentMethod || null
        })
      });
      if (res.ok) {
        setIsEditModalOpen(false);
        fetchInvoices();
      } else {
        const errData = await res.json();
        alert(errData.message || 'Failed to update invoice');
      }
    } catch (err) {
      console.error(err);
      alert('Error updating invoice');
    } finally {
      setIsSavingEdit(false);
    }
  };

  const handleDeleteClick = async (inv) => {
    if (!window.confirm(`Are you sure you want to delete invoice ${inv.invoiceNumber}? This action cannot be undone.`)) {
      return;
    }
    try {
      const res = await fetch(`/api/invoices/${inv.id}`, {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${user?.token || user?.accessToken}`
        }
      });
      if (res.ok) {
        fetchInvoices();
      } else {
        const errData = await res.json();
        alert(errData.message || 'Failed to delete invoice');
      }
    } catch (err) {
      console.error(err);
      alert('Error deleting invoice');
    }
  };

  const handleSelectInvoice = (id) => {
    setSelectedInvoiceIds(prev => 
      prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]
    );
  };

  const handleSelectAll = (filteredList) => {
    const filteredIds = filteredList.map(inv => inv.id);
    const allSelected = filteredIds.length > 0 && filteredIds.every(id => selectedInvoiceIds.includes(id));
    if (allSelected) {
      setSelectedInvoiceIds(prev => prev.filter(id => !filteredIds.includes(id)));
    } else {
      setSelectedInvoiceIds(prev => Array.from(new Set([...prev, ...filteredIds])));
    }
  };

  const handleBulkDelete = async () => {
    if (selectedInvoiceIds.length === 0) return;
    if (!window.confirm(`Are you sure you want to delete the ${selectedInvoiceIds.length} selected invoices? This action cannot be undone.`)) {
      return;
    }
    try {
      const res = await fetch('/api/invoices/bulk-delete', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${user?.token || user?.accessToken}`
        },
        body: JSON.stringify({ ids: selectedInvoiceIds })
      });
      if (res.ok) {
        fetchInvoices();
      } else {
        const errData = await res.json();
        alert(errData.message || 'Failed to delete selected invoices');
      }
    } catch (err) {
      console.error(err);
      alert('Error performing bulk delete');
    }
  };

  const filteredInvoices = invoices.filter(inv =>
    inv.invoiceNumber?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    inv.patient?.fullName?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const discountAmt = selectedInvoice ? (selectedInvoice.totalAmount - selectedInvoice.finalAmount) : 0;

  return (
    <Layout>
      <div className="flex justify-between items-center mb-8">
        <div>
          <h2 className="text-3xl font-extrabold text-slate-900 tracking-tight">Billing &amp; Payments</h2>
          <p className="text-slate-500 mt-1 font-medium">Manage pending payments and generate receipts</p>
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
        <div className="bg-gradient-to-br from-emerald-500 to-teal-600 rounded-2xl p-6 text-white shadow-lg shadow-teal-200 flex items-center justify-between">
          <div>
            <h3 className="font-semibold text-teal-100 mb-2">Total Collected</h3>
            <p className="text-4xl font-bold flex items-center"><IndianRupee className="w-8 h-8 mr-1" />
              {invoices.filter(i => i.paymentStatus === 'PAID').reduce((a, b) => a + b.finalAmount, 0).toLocaleString()}
            </p>
          </div>
          <div className="p-4 bg-white/20 rounded-2xl backdrop-blur-sm"><TrendingUp className="w-10 h-10" /></div>
        </div>
        <div className="bg-gradient-to-br from-orange-400 to-red-500 rounded-2xl p-6 text-white shadow-lg shadow-red-200 flex items-center justify-between">
          <div>
            <h3 className="font-semibold text-orange-100 mb-2">Pending Dues</h3>
            <p className="text-4xl font-bold flex items-center"><IndianRupee className="w-8 h-8 mr-1" />
              {invoices.filter(i => i.paymentStatus === 'UNPAID').reduce((a, b) => a + b.finalAmount, 0).toLocaleString()}
            </p>
          </div>
          <div className="p-4 bg-white/20 rounded-2xl backdrop-blur-sm"><CreditCard className="w-10 h-10" /></div>
        </div>
      </div>

      {/* Table */}
      <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="p-5 border-b border-slate-50 flex justify-between items-center bg-slate-50/50">
          <div className="relative w-96 shadow-sm rounded-xl">
            <input type="text" placeholder="Search invoices by ID or Patient Name..."
              value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-12 pr-4 py-3 border border-slate-200 rounded-xl focus:outline-none focus:ring-4 focus:ring-blue-500/20 focus:border-blue-500 transition-all font-medium text-slate-700"
            />
            <Search className="w-5 h-5 text-slate-400 absolute left-4 top-3.5" />
          </div>

          {user?.userType === 'STAFF' && selectedInvoiceIds.length > 0 && (
            <button
              onClick={handleBulkDelete}
              className="flex items-center gap-2 bg-rose-600 hover:bg-rose-700 text-white font-bold px-5 py-3 rounded-xl shadow-lg shadow-rose-200 transition-all text-sm transform hover:-translate-y-0.5"
            >
              <Trash2 className="w-4 h-4" />
              Delete Selected ({selectedInvoiceIds.length})
            </button>
          )}
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-100">
                {user?.userType === 'STAFF' && (
                  <th className="px-6 py-4 w-12 text-left">
                    <input
                      type="checkbox"
                      className="rounded border-slate-300 text-blue-600 focus:ring-blue-500 w-4 h-4 cursor-pointer"
                      checked={filteredInvoices.length > 0 && filteredInvoices.every(inv => selectedInvoiceIds.includes(inv.id))}
                      onChange={() => handleSelectAll(filteredInvoices)}
                    />
                  </th>
                )}
                {['Invoice No.', 'Patient', 'Amount', 'Date', 'Status', 'Actions'].map(h => (
                  <th key={h} className={`px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider ${h === 'Actions' ? 'text-right' : ''}`}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredInvoices.length > 0 ? filteredInvoices.map(inv => (
                <tr key={inv.id} className="hover:bg-blue-50/30 transition-colors">
                  {user?.userType === 'STAFF' && (
                    <td className="px-6 py-4 w-12 text-left">
                      <input
                        type="checkbox"
                        className="rounded border-slate-300 text-blue-600 focus:ring-blue-500 w-4 h-4 cursor-pointer"
                        checked={selectedInvoiceIds.includes(inv.id)}
                        onChange={() => handleSelectInvoice(inv.id)}
                      />
                    </td>
                  )}
                  <td className="px-6 py-4 font-mono text-sm font-semibold text-blue-600">{inv.invoiceNumber}</td>
                  <td className="px-6 py-4">
                    <p className="text-sm font-bold text-slate-800">{inv.patient?.fullName}</p>
                    <p className="text-xs text-slate-500">{inv.patient?.mobileNumber}</p>
                  </td>
                  <td className="px-6 py-4">
                    <p className="text-sm font-bold text-slate-800">₹{inv.finalAmount}</p>
                    {inv.discount > 0 && <p className="text-xs text-green-600 font-medium">-₹{inv.discount} discount</p>}
                  </td>
                  <td className="px-6 py-4 text-sm font-medium text-slate-600">{new Date(inv.createdAt).toLocaleDateString()}</td>
                  <td className="px-6 py-4">
                    {inv.paymentStatus === 'PAID'
                      ? <span className="inline-flex items-center px-2.5 py-1 rounded-md text-xs font-bold bg-emerald-100 text-emerald-800 border border-emerald-200">PAID</span>
                      : <span className="inline-flex items-center px-2.5 py-1 rounded-md text-xs font-bold bg-rose-100 text-rose-800 border border-rose-200 animate-pulse">PENDING</span>}
                  </td>
                  <td className="px-6 py-4 text-right flex items-center justify-end gap-3">
                    {inv.paymentStatus !== 'PAID' && (
                      <button onClick={() => handlePayClick(inv)}
                        className="bg-blue-600 hover:bg-blue-700 text-white text-xs font-bold px-4 py-2 rounded-lg shadow-sm transition-colors">
                        Collect Payment
                      </button>
                    )}
                    <button className="text-sm font-bold text-slate-600 hover:text-slate-900 flex items-center">
                      <Receipt className="w-4 h-4 mr-1.5" /> Receipt
                    </button>
                    {user?.userType === 'STAFF' && (
                      <>
                        <button onClick={() => handleEditClick(inv)} className="p-2 text-blue-600 hover:text-blue-800 hover:bg-blue-50 rounded-lg transition-colors" title="Edit Invoice">
                          <Pencil className="w-4 h-4" />
                        </button>
                        <button onClick={() => handleDeleteClick(inv)} className="p-2 text-rose-600 hover:text-rose-800 hover:bg-rose-50 rounded-lg transition-colors" title="Delete Invoice">
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </>
                    )}
                  </td>
                </tr>
              )) : (
                <tr><td colSpan={user?.userType === 'STAFF' ? 7 : 6} className="px-6 py-16 text-center">
                  <div className="flex flex-col items-center">
                    <Receipt className="w-12 h-12 text-slate-300 mb-3" />
                    <p className="text-slate-500 font-medium text-lg">No invoices found</p>
                  </div>
                </td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Payment Modal */}
      {isPaymentModalOpen && selectedInvoice && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md flex flex-col" style={{ maxHeight: '92vh', overflowY: 'auto' }}>

            {/* Header */}
            <div className="px-6 py-5 border-b border-slate-100 flex justify-between items-center bg-slate-50 sticky top-0">
              <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                <Wallet className="w-5 h-5 text-blue-600" /> Process Payment
              </h3>
              <button onClick={() => setIsPaymentModalOpen(false)} className="text-slate-400 hover:text-slate-600"><X className="w-6 h-6" /></button>
            </div>

            <div className="p-6 flex flex-col gap-5">
              {/* Amount Summary */}
              <div className="text-center">
                <p className="font-bold text-slate-800 text-base">{selectedInvoice.patient?.fullName}</p>
                <p className="text-xs text-slate-400 mt-0.5">Invoice: {selectedInvoice.invoiceNumber}</p>
                <div className="mt-3 bg-slate-50 rounded-2xl p-4 text-sm">
                  <div className="flex justify-between text-slate-500 mb-1">
                    <span>Total Amount</span>
                    <span className="font-bold text-slate-700">₹{selectedInvoice.totalAmount}</span>
                  </div>
                  {discountAmt > 0 && (
                    <div className="flex justify-between text-green-600 mb-1">
                      <span className="flex items-center gap-1"><Tag className="w-3.5 h-3.5" /> Discount</span>
                      <span className="font-bold">- ₹{discountAmt.toFixed(2)}</span>
                    </div>
                  )}
                  <div className="flex justify-between items-center pt-2 border-t border-slate-200 mt-1">
                    <span className="font-bold text-slate-800">Final Amount</span>
                    <span className="text-3xl font-black text-slate-900">₹{selectedInvoice.finalAmount}</span>
                  </div>
                </div>
              </div>

              {/* Discount Section */}
              <div className="border border-dashed border-slate-200 rounded-2xl p-4">
                <p className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-3 flex items-center gap-1.5">
                  <Tag className="w-3.5 h-3.5" /> Apply Discount
                </p>
                {discountApplied ? (
                  <div className="flex items-center justify-between bg-green-50 border border-green-200 rounded-xl px-3 py-2">
                    <span className="text-sm font-bold text-green-700">✓ Discount: -₹{discountAmt.toFixed(2)}</span>
                    <button onClick={handleRemoveDiscount} className="text-xs text-red-500 hover:text-red-700 font-bold ml-3">Remove</button>
                  </div>
                ) : (
                  <>
                    <div className="grid grid-cols-2 gap-2 mb-3">
                      {[['DOCTOR', '🩺 Referral Doctor', 'purple'], ['LAB', '🏥 Laboratory', 'orange']].map(([val, label, color]) => (
                        <button key={val} onClick={() => setDiscountBy(val)}
                          className={`py-2.5 rounded-xl text-xs font-bold border-2 transition-all ${
                            discountBy === val
                              ? 'border-slate-200'
                              : 'border-slate-200 text-slate-500 hover:border-slate-300'
                          }`}
                          style={discountBy === val ? { borderColor: color === 'purple' ? '#a855f7' : '#f97316', background: color === 'purple' ? '#faf5ff' : '#fff7ed', color: color === 'purple' ? '#7e22ce' : '#c2410c' } : {}}
                        >
                          {label}
                        </button>
                      ))}
                    </div>
                    {discountBy && (
                      <div className="space-y-2">
                        <div className="flex bg-slate-100 rounded-lg p-0.5">
                          <button onClick={() => setDiscountType('PERCENT')}
                            className={`flex-1 py-1.5 rounded-md text-xs font-bold transition-all ${discountType === 'PERCENT' ? 'bg-white shadow text-slate-800' : 'text-slate-500'}`}>
                            <Percent className="w-3 h-3 inline mr-1" /> Percentage (%)
                          </button>
                          <button onClick={() => setDiscountType('FIXED')}
                            className={`flex-1 py-1.5 rounded-md text-xs font-bold transition-all ${discountType === 'FIXED' ? 'bg-white shadow text-slate-800' : 'text-slate-500'}`}>
                            <IndianRupee className="w-3 h-3 inline mr-1" /> Fixed (₹)
                          </button>
                        </div>
                        <div className="flex gap-2">
                          <input type="number" min="0" max={discountType === 'PERCENT' ? '100' : selectedInvoice.totalAmount}
                            step="0.5" value={discountValue} onChange={e => setDiscountValue(e.target.value)}
                            placeholder={discountType === 'PERCENT' ? 'e.g. 10' : 'e.g. 100'}
                            className="flex-1 border-2 border-slate-200 rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-blue-500 font-medium"
                          />
                          <button onClick={handleApplyDiscount} disabled={isApplyingDiscount || !discountValue}
                            className="bg-[#00488d] hover:bg-blue-800 disabled:opacity-50 text-white px-4 py-2 rounded-xl text-xs font-bold transition-colors whitespace-nowrap">
                            {isApplyingDiscount ? '...' : 'Apply'}
                          </button>
                        </div>
                        {discountValue && (
                          <p className="text-xs text-slate-400 text-center">
                            Saves ₹{discountType === 'PERCENT'
                              ? ((selectedInvoice.totalAmount * parseFloat(discountValue || 0)) / 100).toFixed(2)
                              : parseFloat(discountValue || 0).toFixed(2)
                            } → Pay ₹{Math.max(0, selectedInvoice.totalAmount - (discountType === 'PERCENT'
                              ? (selectedInvoice.totalAmount * parseFloat(discountValue || 0)) / 100
                              : parseFloat(discountValue || 0))).toFixed(2)}
                          </p>
                        )}
                      </div>
                    )}
                  </>
                )}
              </div>

              {/* Payment Method */}
              <div className="grid grid-cols-2 gap-3">
                {[['CASH', <IndianRupee className="w-5 h-5" />, 'Cash'], ['UPI', <QrCode className="w-5 h-5" />, 'UPI / QR']].map(([val, icon, label]) => (
                  <button key={val} onClick={() => setPaymentMethod(val)}
                    className={`py-3 px-4 rounded-xl border-2 font-bold flex items-center justify-center gap-2 transition-all ${
                      paymentMethod === val ? 'border-blue-600 bg-blue-50 text-blue-700' : 'border-slate-200 text-slate-600 hover:border-slate-300'
                    }`}>
                    {icon} {label}
                  </button>
                ))}
              </div>

              {/* UPI QR */}
              {paymentMethod === 'UPI' && (
                <div className="flex flex-col items-center p-5 bg-blue-50/50 rounded-2xl border border-blue-100">
                  <p className="text-sm font-bold text-blue-800 mb-4 text-center">
                    Scan with any UPI App<br />
                    <span className="text-xs font-medium text-blue-600">(Google Pay, PhonePe, Paytm)</span>
                  </p>
                  <div className="bg-white p-3 rounded-xl shadow-sm border border-slate-200">
                    <QRCodeSVG
                      value={`upi://pay?pa=sanapathologylab@axl&pn=SanaPathologyLab&am=${selectedInvoice.finalAmount}&cu=INR`}
                      size={180} level="H" includeMargin={true}
                    />
                  </div>
                  <p className="text-xs font-mono font-medium text-slate-500 mt-3 bg-white px-3 py-1.5 rounded-lg shadow-sm border border-slate-100">
                    sanapathologylab@axl
                  </p>
                  <p className="text-sm font-bold text-blue-700 mt-1">Amount: ₹{selectedInvoice.finalAmount}</p>
                </div>
              )}

              {/* Confirm Button */}
              <button onClick={handleProcessPayment} disabled={isProcessing}
                className="w-full py-4 rounded-xl bg-slate-900 hover:bg-slate-800 text-white font-bold flex items-center justify-center gap-2 transition-colors disabled:opacity-70 shadow-lg shadow-slate-900/20">
                {isProcessing
                  ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                  : <><CheckCircle2 className="w-5 h-5" /> Mark as Paid ({paymentMethod})</>
                }
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Edit Invoice Modal */}
      {isEditModalOpen && editInvoice && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md flex flex-col" style={{ maxHeight: '92vh', overflowY: 'auto' }}>
            
            {/* Header */}
            <div className="px-6 py-5 border-b border-slate-100 flex justify-between items-center bg-slate-50 sticky top-0">
              <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                <Pencil className="w-5 h-5 text-blue-600" /> Edit Invoice
              </h3>
              <button onClick={() => setIsEditModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="p-6 flex flex-col gap-5">
              {/* Summary */}
              <div className="bg-slate-50 rounded-2xl p-4 text-sm">
                <div className="flex justify-between text-slate-500 mb-1">
                  <span>Invoice Number</span>
                  <span className="font-bold text-slate-700">{editInvoice.invoiceNumber}</span>
                </div>
                <div className="flex justify-between text-slate-500 mb-1">
                  <span>Patient</span>
                  <span className="font-bold text-slate-700">{editInvoice.patient?.fullName}</span>
                </div>
                <div className="flex justify-between text-slate-500">
                  <span>Original Total</span>
                  <span className="font-bold text-slate-700">₹{editInvoice.totalAmount}</span>
                </div>
              </div>

              {/* Form Fields */}
              <div className="space-y-4">
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Discount (₹)</label>
                  <input
                    type="number"
                    min="0"
                    value={editDiscount}
                    onChange={(e) => {
                      const disc = parseFloat(e.target.value) || 0;
                      setEditDiscount(e.target.value);
                      setEditFinalAmount(Math.max(0, editInvoice.totalAmount - disc).toString());
                    }}
                    className="w-full border-2 border-slate-200 rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-blue-500 font-medium"
                    placeholder="Discount amount"
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Final Amount (₹)</label>
                  <input
                    type="number"
                    min="0"
                    value={editFinalAmount}
                    onChange={(e) => setEditFinalAmount(e.target.value)}
                    className="w-full border-2 border-slate-200 rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-blue-500 font-medium"
                    placeholder="Final payable amount"
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Payment Status</label>
                  <select
                    value={editPaymentStatus}
                    onChange={(e) => setEditPaymentStatus(e.target.value)}
                    className="w-full border-2 border-slate-200 rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-blue-500 font-medium bg-white"
                  >
                    <option value="UNPAID">UNPAID</option>
                    <option value="PARTIAL">PARTIAL</option>
                    <option value="PAID">PAID</option>
                  </select>
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Payment Method</label>
                  <select
                    value={editPaymentMethod}
                    onChange={(e) => setEditPaymentMethod(e.target.value)}
                    className="w-full border-2 border-slate-200 rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-blue-500 font-medium bg-white"
                  >
                    <option value="">None / Select Method</option>
                    <option value="CASH">CASH</option>
                    <option value="UPI">UPI</option>
                    <option value="CC">CREDIT CARD</option>
                    <option value="DC">DEBIT CARD</option>
                    <option value="BANK">BANK TRANSFER</option>
                  </select>
                </div>
              </div>

              {/* Action Buttons */}
              <div className="flex gap-3 mt-2">
                <button
                  onClick={() => setIsEditModalOpen(false)}
                  className="flex-1 py-3.5 rounded-xl border-2 border-slate-200 hover:border-slate-300 text-slate-600 font-bold transition-colors"
                >
                  Cancel
                </button>
                <button
                  onClick={handleSaveEdit}
                  disabled={isSavingEdit}
                  className="flex-1 py-3.5 rounded-xl bg-slate-900 hover:bg-slate-800 text-white font-bold flex items-center justify-center gap-2 transition-colors disabled:opacity-70 shadow-lg shadow-slate-900/20"
                >
                  {isSavingEdit ? (
                    <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                  ) : (
                    'Save Changes'
                  )}
                </button>
              </div>

            </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default Billing;

import React, { useState, useEffect } from 'react';
import { useLanguage } from '../context/LanguageContext';
import {
  Calendar, UserCircle, Phone, MapPin, Clock, Heart, CheckCircle2,
  Loader2, ArrowRight, X, Info, ShieldCheck, Trash2
} from 'lucide-react';
import PublicHomeHeader from '../components/PublicHomeHeader';
import EmergencyWidget from '../components/EmergencyWidget';
import LiveChatWidget from '../components/LiveChatWidget';

const API = import.meta.env.VITE_API_URL || 'http://localhost:5000/api';

const BookOnlinePage = () => {
  const { t, language } = useLanguage();

  const [selectedTests, setSelectedTests] = useState(() => {
    try { return JSON.parse(localStorage.getItem('sana_cart')) || []; } catch { return []; }
  });

  const [form, setForm] = useState({
    name: '', mobile: '', gender: 'MALE', address: '',
    preferredDate: new Date(Date.now() + 86400000).toISOString().split('T')[0],
    preferredTime: '08:00', isHomeCollection: true
  });

  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState('');
  const [appointment, setAppointment] = useState(null);

  useEffect(() => { window.scrollTo(0, 0); }, []);

  const totalPrice = selectedTests.reduce((acc, t) => acc + t.price, 0);

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setForm(prev => ({ ...prev, [name]: type === 'checkbox' ? checked : value }));
  };

  const removeTest = (code) => {
    const updated = selectedTests.filter(t => t.testCode !== code);
    setSelectedTests(updated);
    localStorage.setItem('sana_cart', JSON.stringify(updated));
  };

  const clearCart = () => {
    setSelectedTests([]);
    localStorage.setItem('sana_cart', JSON.stringify([]));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (selectedTests.length === 0) {
      setError('Please select at least one test or health package.');
      return;
    }
    setLoading(true);
    setError('');
    const testListStr = selectedTests.map(t => `${t.name} (₹${t.price})`).join(', ');
    const notesContent = `Requested via Book Online Page. Tests/Packages: ${testListStr}. Mode: ${form.isHomeCollection ? 'Home Collection' : 'Lab Visit'}`;
    try {
      const response = await fetch('/api/public/book-appointment', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: form.name, mobile: form.mobile, gender: form.gender,
          address: form.isHomeCollection ? form.address : 'Lab Visit',
          preferredDate: form.preferredDate, preferredTime: form.preferredTime,
          notes: notesContent
        })
      });
      if (response.ok) {
        const data = await response.json();
        setAppointment(data.appointment);
        setSuccess(true);
        const msg = `*New Appointment Request (Online)*\n\n*Name:* ${form.name}\n*Mobile:* ${form.mobile}\n*Gender:* ${form.gender}\n*Date:* ${form.preferredDate} ${form.preferredTime}\n*Mode:* ${form.isHomeCollection ? 'Home Collection' : 'Clinic Visit'}\n\n*Tests:*\n${testListStr}\n\n*Total:* ₹${totalPrice}`;
        window.open(`https://wa.me/916396786939?text=${encodeURIComponent(msg)}`, '_blank');
      } else {
        const data = await response.json();
        setError(data.message || 'Failed to submit. Please try again.');
      }
    } catch {
      setError('Network error. Failed to connect.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-bg font-sans text-slate-800">
      <PublicHomeHeader cartCount={selectedTests.length} />

      {/* Hero */}
      <section className="relative pt-24 pb-28 overflow-hidden bg-gradient-to-br from-[#063b30] via-[#085041] to-[#0b6b55]">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10 text-center">
          <div className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-white/10 text-emerald-200 text-xs font-bold tracking-wider uppercase mb-6 backdrop-blur-md border border-white/20">
            <Calendar size={14} className="text-[#F1C40F]" />
            {t('oneMinBooking')}
          </div>
          <h1 className="text-4xl md:text-6xl font-heading font-black text-white leading-tight mb-4">
            {t('bookHomeSample')}
          </h1>
          <p className="text-lg md:text-xl text-emerald-100/80 max-w-2xl mx-auto font-medium">
            {t('fillDetails')}
          </p>
        </div>
      </section>

      {/* Booking Section */}
      <section className="py-12 px-4 sm:px-6 lg:px-8 -mt-16 relative z-20">
        <div className="max-w-5xl mx-auto grid grid-cols-1 lg:grid-cols-5 gap-8">
          {/* Form */}
          <div className="lg:col-span-3">
            <div className="bg-white rounded-3xl shadow-lg border border-slate-100 p-6 md:p-8">
              {success && appointment ? (
                <div className="text-center py-8">
                  <div className="w-20 h-20 rounded-full bg-emerald-100 flex items-center justify-center mx-auto mb-6">
                    <CheckCircle2 className="w-10 h-10 text-emerald-600" />
                  </div>
                  <h3 className="text-2xl font-black text-slate-800 mb-2">{t('requestSubmitted')}</h3>
                  <p className="text-slate-500 font-semibold mb-6">
                    {language === 'hi'
                      ? `धन्यवाद, ${form.name}। आपका अनुरोध प्राप्त हो गया है।`
                      : `Thank you, ${form.name}. Your request has been received.`}
                  </p>
                  <div className="bg-primary-pale rounded-2xl p-5 border border-primary/20 mb-6">
                    <p className="text-xs font-black text-primary uppercase tracking-wider mb-1">{t('trackingRefId')}</p>
                    <p className="text-2xl font-black text-slate-800 font-mono">SPL-APT-{String(appointment.id).padStart(6, '0')}</p>
                  </div>
                  <button
                    onClick={() => { setSuccess(false); setForm({
                      name: '', mobile: '', gender: 'MALE', address: '',
                      preferredDate: new Date(Date.now() + 86400000).toISOString().split('T')[0],
                      preferredTime: '08:00', isHomeCollection: true
                    }); }}
                    className="bg-primary text-white px-8 py-3.5 rounded-2xl font-bold text-sm"
                  >
                    {t('bookAnother')}
                  </button>
                </div>
              ) : (
                <form onSubmit={handleSubmit} className="space-y-5">
                  {/* Selected Tests Summary */}
                  {selectedTests.length > 0 && (
                    <div className="bg-primary-pale/30 rounded-2xl p-4 border border-primary/10 mb-2">
                      <div className="flex items-center justify-between mb-3">
                        <h4 className="text-xs font-black text-primary uppercase tracking-wider flex items-center gap-1.5">
                          <Heart size={14} className="text-red-400" />
                          {t('selectedTestsCount').replace('{count}', selectedTests.length)}
                        </h4>
                        <button type="button" onClick={clearCart} className="text-[10px] font-bold text-red-500 hover:text-red-700 flex items-center gap-1">
                          <Trash2 size={12} /> Clear
                        </button>
                      </div>
                      <div className="space-y-1.5">
                        {selectedTests.map(item => (
                          <div key={item.testCode} className="flex items-center justify-between bg-white rounded-xl px-3 py-2 border border-primary/5">
                            <span className="text-xs font-bold text-slate-700">{item.name}</span>
                            <div className="flex items-center gap-2">
                              <span className="text-xs font-black text-primary">₹{item.price}</span>
                              <button type="button" onClick={() => removeTest(item.testCode)} className="text-slate-300 hover:text-red-400 transition-colors">
                                <X size={14} />
                              </button>
                            </div>
                          </div>
                        ))}
                      </div>
                      <div className="flex justify-between items-center mt-3 pt-3 border-t border-primary/10">
                        <span className="text-xs font-bold text-slate-500">{t('totalPrice')}</span>
                        <span className="text-lg font-black text-primary">₹{totalPrice}</span>
                      </div>
                    </div>
                  )}

                  {selectedTests.length === 0 && (
                    <div className="bg-amber-50 border border-amber-200 rounded-2xl p-5 text-center mb-2">
                      <Info className="w-8 h-8 text-amber-400 mx-auto mb-2" />
                      <p className="text-sm font-bold text-amber-800">{t('noSelectedTestsWarning')}</p>
                      <button
                        type="button"
                        onClick={() => window.location.href = '/test-finder'}
                        className="mt-3 text-sm font-bold text-primary hover:text-primary-light underline"
                      >
                        Browse Tests →
                      </button>
                    </div>
                  )}

                  <div className="space-y-1">
                    <label className="block text-xs font-black text-slate-500 uppercase tracking-wider">{t('patientName')}</label>
                    <input type="text" name="name" value={form.name} onChange={handleChange}
                      placeholder={t('enterName')}
                      className="w-full border-2 border-slate-100 rounded-2xl px-4 py-3.5 text-sm font-semibold focus:outline-none focus:border-primary focus:ring-4 focus:ring-primary/10 bg-white transition-all" required />
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div className="space-y-1">
                      <label className="block text-xs font-black text-slate-500 uppercase tracking-wider">{t('mobileNumber')}</label>
                      <input type="tel" name="mobile" value={form.mobile} onChange={handleChange}
                        placeholder={t('enterMobile')} maxLength={10}
                        className="w-full border-2 border-slate-100 rounded-2xl px-4 py-3.5 text-sm font-semibold focus:outline-none focus:border-primary focus:ring-4 focus:ring-primary/10 bg-white transition-all" required />
                    </div>
                    <div className="space-y-1">
                      <label className="block text-xs font-black text-slate-500 uppercase tracking-wider">{t('genderLabel')}</label>
                      <div className="grid grid-cols-3 gap-2">
                        {['MALE', 'FEMALE', 'OTHER'].map(g => (
                          <button key={g} type="button" onClick={() => setForm(prev => ({ ...prev, gender: g }))}
                            className={`py-3 text-xs font-bold rounded-2xl border-2 transition-all ${
                              form.gender === g
                                ? 'bg-primary text-white border-primary shadow-md'
                                : 'bg-slate-50 text-slate-600 border-slate-100 hover:border-slate-200'
                            }`}>
                            {g === 'MALE' ? (language === 'hi' ? 'पुरुष' : 'Male') : g === 'FEMALE' ? (language === 'hi' ? 'महिला' : 'Female') : (language === 'hi' ? 'अन्य' : 'Other')}
                          </button>
                        ))}
                      </div>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div className="space-y-1">
                      <label className="block text-xs font-black text-slate-500 uppercase tracking-wider">{t('preferredDate')}</label>
                      <input type="date" name="preferredDate" value={form.preferredDate} onChange={handleChange}
                        className="w-full border-2 border-slate-100 rounded-2xl px-4 py-3.5 text-sm font-semibold focus:outline-none focus:border-primary focus:ring-4 focus:ring-primary/10 bg-white transition-all" required />
                    </div>
                    <div className="space-y-1">
                      <label className="block text-xs font-black text-slate-500 uppercase tracking-wider">{t('preferredTime')}</label>
                      <input type="time" name="preferredTime" value={form.preferredTime} onChange={handleChange}
                        className="w-full border-2 border-slate-100 rounded-2xl px-4 py-3.5 text-sm font-semibold focus:outline-none focus:border-primary focus:ring-4 focus:ring-primary/10 bg-white transition-all" required />
                    </div>
                  </div>

                  <div className="space-y-2">
                    <label className="block text-xs font-black text-slate-500 uppercase tracking-wider">{t('collectionMode')}</label>
                    <div className="grid grid-cols-2 gap-3">
