    setLoading(true);
    try {
      const [aptRes, staffRes] = await Promise.all([
        fetch(`${API}/appointments`, { headers }),
        fetch(`${API}/staff`, { headers })
      ]);

      if (aptRes.ok && staffRes.ok) {
        const aptData = await aptRes.json();
        const staffData = await staffRes.json();
        
        // Filter appointments for HOME_COLLECTION type
        const collectionsOnly = Array.isArray(aptData) 
          ? aptData.filter(a => a.type === 'HOME_COLLECTION') 
          : [];
        
        setAppointments(collectionsOnly);
        setStaffList(Array.isArray(staffData) ? staffData : []);
      }
    } catch (err) {
      console.error('Failed to fetch collections data:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (user) {
      fetchData();
    }
  }, [user]);

  const handleAssignPhlebotomist = async (appointmentId, staffId) => {
    try {
      const response = await fetch(`${API}/appointments/${appointmentId}`, {
        method: 'PUT',
        headers,
        body: JSON.stringify({ assignedToId: staffId ? parseInt(staffId) : null })
      });
      if (response.ok) {
        // Update local state
        setAppointments(prev => prev.map(apt => {
          if (apt.id === appointmentId) {
            const staffMember = staffList.find(s => s.id === parseInt(staffId));
            return { ...apt, assignedToId: staffId ? parseInt(staffId) : null, assignedTo: staffMember || null };
          }
          return apt;
        }));
      } else {
        alert('Failed to assign phlebotomist.');
      }
    } catch (err) {
      console.error('Assign phlebotomist error:', err);
    }
  };

  const handleMarkCollected = async (appointmentId) => {
    try {
      const response = await fetch(`${API}/appointments/${appointmentId}`, {
        method: 'PUT',
        headers,
        body: JSON.stringify({ status: 'COMPLETED' })
      });
      if (response.ok) {
        setAppointments(prev => prev.map(apt => {
          if (apt.id === appointmentId) {
            return { ...apt, status: 'COMPLETED' };
          }
          return apt;
        }));
      } else {
        alert('Failed to update collection status.');
      }
    } catch (err) {
      console.error('Mark collected error:', err);
    }
  };

  // Filter staff list to only active technicians/phlebotomists
  const phlebotomists = staffList.filter(s => s.isActive && (s.role === 'TECHNICIAN' || s.role === 'HELPER' || s.role === 'OTHER'));

  // Filter and search logic
  const filteredAppointments = appointments.filter(apt => {
    const matchesStatus = filterStatus === 'ALL' || apt.status === filterStatus;
    const patientName = apt.patient?.fullName?.toLowerCase() || '';
    const patientMobile = apt.patient?.mobileNumber || '';
    const address = apt.address?.toLowerCase() || '';
    const refId = `SPL-APT-${apt.id.toString().padStart(6, '0')}`.toLowerCase();
    
    const matchesSearch = 
      patientName.includes(searchTerm.toLowerCase()) ||
      patientMobile.includes(searchTerm) ||
      address.includes(searchTerm.toLowerCase()) ||
      refId.includes(searchTerm.toLowerCase());
      
    return matchesStatus && matchesSearch;
  });

  return (
    <Layout>
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
        <div>
          <h1 className="text-2xl font-extrabold text-[#00488d] uppercase tracking-wide">Home Sample Collections</h1>
          <p className="text-sm text-gray-500 mt-1">
            Track and manage home visits, phlebotomist assignments, and collection updates.
          </p>
        </div>
        <button 
          onClick={fetchData}
          className="flex items-center justify-center gap-2 bg-slate-100 hover:bg-slate-200 text-slate-700 px-4 py-2 rounded-xl font-bold text-sm transition-colors border border-slate-200 shadow-sm"
        >
          <RefreshCw className="w-4 h-4" /> Refresh Data
        </button>
      </div>

      {/* Filters and Search */}
      <div className="bg-white border border-slate-200 rounded-2xl p-4 shadow-sm mb-6 flex flex-col md:flex-row gap-4 items-center justify-between">
        <div className="flex flex-wrap gap-2 w-full md:w-auto">
          {['ALL', 'SCHEDULED', 'COMPLETED', 'CANCELLED'].map(status => (
            <button
              key={status}
              onClick={() => setFilterStatus(status)}
              className={`px-4 py-2 rounded-xl text-xs font-bold uppercase transition-all ${
                filterStatus === status 
                  ? 'bg-[#00488d] text-white' 
                  : 'bg-slate-50 border border-slate-200 text-slate-600 hover:bg-slate-100'
              }`}
            >
              {status} ({
                status === 'ALL' 
                  ? appointments.length 
                  : appointments.filter(a => a.status === status).length
              })
            </button>
          ))}
        </div>
        <div className="w-full md:w-72">
          <input
            type="text"
            placeholder="Search by patient name, mobile, address, ref..."
            value={searchTerm}
            onChange={e => setSearchTerm(e.target.value)}
            className="w-full px-4 py-2 border border-slate-200 rounded-xl text-xs font-semibold focus:outline-none focus:border-[#00488d] transition-colors"
          />
        </div>
      </div>

      {loading ? (
        <div className="flex items-center justify-center min-h-[40vh]">
          <Loader type="page" size="md" />
        </div>
      ) : (
        <div className="space-y-4">
          {filteredAppointments.length === 0 ? (
            <div className="text-center py-16 text-slate-400 bg-white rounded-2xl border border-slate-200">
              <ClipboardList className="w-12 h-12 mx-auto mb-3 text-slate-300" />
              <p className="font-bold">No home collection requests found</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 gap-4">
              {filteredAppointments.map(apt => (
                <div 
                  key={apt.id} 
                  className={`bg-white rounded-2xl border transition-all p-5 shadow-sm hover:shadow-md flex flex-col md:flex-row justify-between gap-5 ${
                    apt.status === 'COMPLETED' 
                      ? 'border-emerald-100 bg-emerald-50/5' 
                      : apt.status === 'CANCELLED' 
                        ? 'border-red-100 bg-red-50/5' 
                        : 'border-slate-200 hover:border-[#00488d]'
                  }`}
                >
                  <div className="flex-1 space-y-3">
                    <div className="flex flex-wrap items-center gap-2">
                      <span className="text-xs font-black bg-blue-50 text-[#00488d] px-2.5 py-1 rounded-lg font-mono">
                        SPL-APT-{apt.id.toString().padStart(6, '0')}
                      </span>
                      <span className={`text-[10px] font-extrabold px-2.5 py-1 rounded-full uppercase tracking-wider ${
                        apt.status === 'COMPLETED' 
                          ? 'bg-emerald-100 text-emerald-800' 
                          : apt.status === 'CANCELLED' 
                            ? 'bg-red-100 text-red-800' 
                            : 'bg-amber-100 text-amber-800'
                      }`}>
                        {apt.status}
                      </span>
                    </div>

                    <div>
                      <h3 className="text-base font-bold text-slate-800">{apt.patient?.fullName}</h3>
                      <p className="text-xs text-slate-500 font-semibold mt-0.5">
                        {apt.patient?.patientId} · {apt.patient?.gender} · {apt.patient?.age} Yrs · {apt.patient?.mobileNumber}
                      </p>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-2 text-xs text-slate-600">
                      <div className="flex items-center gap-1.5">
                        <Calendar className="w-4 h-4 text-slate-400 shrink-0" />
                        <span>Date: <strong className="text-slate-700">{new Date(apt.date).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })}</strong></span>
                      </div>
                      <div className="flex items-center gap-1.5">
                        <Clock className="w-4 h-4 text-slate-400 shrink-0" />
                        <span>Time Slot: <strong className="text-slate-700">{apt.time}</strong></span>
                      </div>
                      <div className="col-span-1 sm:col-span-2 flex items-start gap-1.5">
                        <MapPin className="w-4 h-4 text-slate-400 shrink-0 mt-0.5" />
                        <span>Address: <strong className="text-slate-700">{apt.address || 'N/A'}</strong></span>
                      </div>
                      {apt.notes && (
                        <div className="col-span-1 sm:col-span-2 bg-slate-50 p-2.5 rounded-xl border border-slate-100 mt-1">
                          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wide">Patient Notes</p>
                          <p className="text-slate-700 mt-0.5 font-medium">{apt.notes}</p>
                        </div>
                      )}
                    </div>
                  </div>

                  <div className="flex flex-col justify-between sm:items-end gap-4 min-w-[200px] border-t md:border-t-0 pt-4 md:pt-0 border-slate-100">
                    <div className="space-y-2 w-full">
                      <label className="block text-[10px] font-extrabold uppercase text-slate-400 tracking-wider">
                        Phlebotomist Assigned
                      </label>
                      {apt.status === 'COMPLETED' || apt.status === 'CANCELLED' ? (
                        <div className="flex items-center gap-2 text-xs font-bold text-slate-600 bg-slate-50 border border-slate-100 rounded-xl px-3 py-2">
                          <UserCheck className="w-4 h-4 text-slate-400" />
                          <span>{apt.assignedTo?.name || 'None Assigned'}</span>
                        </div>
                      ) : (
                        <select
                          value={apt.assignedToId || ''}
                          onChange={e => handleAssignPhlebotomist(apt.id, e.target.value)}
                          className="w-full bg-white border border-slate-200 text-xs font-bold rounded-xl px-3 py-2 text-slate-700 focus:ring-2 focus:ring-[#00488d] transition-all outline-none"
                        >
                          <option value="">-- Assign Staff --</option>
                          {phlebotomists.map(staff => (
                            <option key={staff.id} value={staff.id}>
                              {staff.name} ({staff.role})
                            </option>
                          ))}
                        </select>
                      )}
                    </div>

                    {apt.status === 'SCHEDULED' && (
                      <button
                        onClick={() => handleMarkCollected(apt.id)}
                        className="w-full bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-xs py-2.5 rounded-xl transition-all shadow-sm hover:shadow flex items-center justify-center gap-1.5"
                      >
                        <CheckCircle2 className="w-4 h-4" />
                        <span>Mark Collected</span>
                      </button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </Layout>
  );
};

export default Collections;

import React, { useState } from 'react';
import PublicLayout from '../components/PublicLayout';
import { Calendar, Building2, Users, FileSpreadsheet, Check, Send, Sparkles } from 'lucide-react';
import Loader from '../components/Loader';

const CORPORATE_PACKAGES = [
  {
    name: "Basic Wellness Screening",
    price: 499,
    minSize: "50+ Employees",
    desc: "Essential health audit covering metabolic and hematology baselines.",
    features: [
      "Complete Blood Count (CBC)",
      "Random Blood Sugar (RBS)",
      "Serum Cholesterol",
      "Urine Routine & Microscopy",
      "Doctor Consultation / Consultation summary"
    ]
  },
  {
    name: "Executive Health Panel",
    price: 999,
    minSize: "20+ Employees",
    desc: "Comprehensive metabolic screening for executives and senior staff.",
    features: [
      "Complete Blood Count (CBC)",
      "Liver Function Test (LFT)",
      "Kidney Function Test (KFT)",
      "Lipid Profile (Fats Panel)",
      "Fasting Blood Sugar (FBS)",
      "HbA1c (3-Month Sugar Average)",
      "Urine Routine & Microscopy"
    ]
  },
  {
    name: "Premium Corporate Care",
    price: 1499,
    minSize: "10+ Employees",
    desc: "Complete wellness panel assessing cardiac risk, vitamins, and organ health.",
    features: [
      "Executive Health Panel (All 7 panels)",
      "Vitamin D (25-Hydroxy)",
      "Thyroid Function Test (T3, T4, TSH)",
      "Serum Calcium & Bone Health",
      "Uric Acid"
    ]
  }
];

const Corporate = () => {
  const [form, setForm] = useState({
    companyName: '',
    contactPerson: '',
    mobile: '',
    noOfEmployees: '',
    preferredDate: '',
    notes: ''
  });
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    setSuccess('');

    try {
      const res = await fetch('/api/public/b2b-inquiry', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(form)
      });
      const data = await res.json();
      if (!res.ok) {
        setError(data.message || 'Failed to submit inquiry.');
      } else {
        setSuccess(data.message);
        setForm({
          companyName: '',
          contactPerson: '',
          mobile: '',
          noOfEmployees: '',
          preferredDate: '',
          notes: ''
        });
      }
    } catch {
      setError('Could not connect to the server. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <PublicLayout>
      <div className="bg-[#F5F7F6]">
        
        {/* Banner Section */}
        <section className="bg-gradient-to-r from-[#085041] to-[#0F6E56] py-16 md:py-24 text-white text-center px-6 relative overflow-hidden">
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_top_right,rgba(255,255,255,0.05),transparent)]"></div>
          <div className="max-w-4xl mx-auto relative z-10 space-y-4">
            <span className="bg-[#BA7517]/20 text-[#ffb800] text-xs font-black uppercase px-4 py-1.5 rounded-full border border-[#BA7517]/30 tracking-widest inline-block">
              Corporate Health Services
            </span>
            <h1 className="text-3xl md:text-5xl font-black font-heading leading-tight tracking-tight">
              Annual Health Checkup Drives for Organizations
            </h1>
            <p className="text-sm md:text-lg text-emerald-100 max-w-2xl mx-auto leading-relaxed">
              Empower your workforce with convenient, premium diagnostic camps. On-site collection, NABL standards, and secure digital reports.
            </p>
          </div>
        </section>

        {/* Benefits Section */}
        <section className="py-16 px-6 max-w-7xl mx-auto">
          <div className="text-center max-w-2xl mx-auto mb-12 space-y-3">
            <h2 className="text-2xl md:text-3xl font-extrabold text-slate-800 tracking-tight font-heading">
              Why Choose Sana Pathology for B2B?
            </h2>
            <p className="text-slate-500 text-xs md:text-sm">
              Tailored health packages, structured campaigns, and minimal organizational disruption.
            </p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            <div className="bg-white p-8 rounded-3xl border border-slate-100 shadow-md hover:shadow-xl transition-all duration-300">
              <div className="bg-[#1D9E75]/10 p-3.5 rounded-2xl text-[#1D9E75] inline-block mb-5">
                <Users className="w-6 h-6" />
              </div>
              <h3 className="text-lg font-bold text-slate-800 mb-3">On-Site Camp Collection</h3>
              <p className="text-slate-600 text-sm leading-relaxed">
                Our certified phlebotomists set up structured, hygienic collection camps directly at your office or factory premises.
              </p>
            </div>

            <div className="bg-white p-8 rounded-3xl border border-slate-100 shadow-md hover:shadow-xl transition-all duration-300">
              <div className="bg-[#1D9E75]/10 p-3.5 rounded-2xl text-[#1D9E75] inline-block mb-5">
                <Building2 className="w-6 h-6" />
              </div>
              <h3 className="text-lg font-bold text-slate-800 mb-3">Bulk Report Delivery</h3>
              <p className="text-slate-600 text-sm leading-relaxed">
                All employee reports are generated securely, signed by pathologists, and shared digitally via SMS/WhatsApp within 24 hours.
              </p>
            </div>

            <div className="bg-white p-8 rounded-3xl border border-slate-100 shadow-md hover:shadow-xl transition-all duration-300">
              <div className="bg-[#1D9E75]/10 p-3.5 rounded-2xl text-[#1D9E75] inline-block mb-5">
                <FileSpreadsheet className="w-6 h-6" />
              </div>
              <h3 className="text-lg font-bold text-slate-800 mb-3">Digital MIS Reports</h3>
              <p className="text-slate-600 text-sm leading-relaxed">
                Management receives a comprehensive, anonymous health statistics MIS excel dashboard showing aggregate trends to design wellness activities.
              </p>
            </div>
          </div>
        </section>

        {/* Corporate Tiers Section */}
        <section className="py-16 bg-white px-6 border-y border-slate-100">
          <div className="max-w-7xl mx-auto">
            <div className="text-center max-w-2xl mx-auto mb-12 space-y-3">
              <h2 className="text-2xl md:text-3xl font-extrabold text-slate-800 tracking-tight font-heading">
                Corporate Package Tiers
              </h2>
              <p className="text-slate-500 text-xs md:text-sm">
                Subsidized pricing tailored for high-volume diagnostic checkup camps.
              </p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
              {CORPORATE_PACKAGES.map((pkg, idx) => (
                <div key={idx} className="bg-[#F5F7F6] rounded-3xl p-8 border border-slate-100 flex flex-col justify-between shadow-inner">
                  <div className="space-y-4">
                    <span className="bg-slate-200 text-slate-600 text-[10px] font-black uppercase px-2.5 py-1 rounded">
                      {pkg.minSize}
                    </span>
                    <h3 className="text-xl font-black text-slate-800">{pkg.name}</h3>
                    <p className="text-xs text-slate-500 leading-relaxed">{pkg.desc}</p>
                    <div className="text-2xl font-black text-[#1D9E75] pt-2">₹{pkg.price}<span className="text-xs text-slate-400 font-semibold"> / employee</span></div>
                    
                    <ul className="space-y-2.5 pt-4 text-xs sm:text-sm text-slate-600 border-t border-slate-200/50">
                      {pkg.features.map((feat, fIdx) => (
                        <li key={fIdx} className="flex items-start gap-2">
                          <Check size={16} className="text-[#1D9E75] shrink-0 mt-0.5" />
                          <span>{feat}</span>
                        </li>
                      ))}
                    </ul>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </section>

        {/* Inquiry Form Section */}
        <section className="py-16 px-6 max-w-3xl mx-auto">
          <div className="bg-white rounded-3xl p-8 md:p-12 border border-slate-100 shadow-xl shadow-slate-100/50">
            <div className="text-center mb-8 relative">
              <div className="inline-flex items-center justify-center w-16 h-16 bg-[#1D9E75]/10 rounded-2xl mb-4 border border-[#1D9E75]/10 text-[#1D9E75] shadow-lg shadow-[#1D9E75]/5">
                <Building2 className="w-8 h-8" />
              </div>
              <h2 className="text-2xl md:text-3xl font-extrabold text-[#085041] tracking-tight font-heading">
                Request B2B Quote
              </h2>
              <p className="text-slate-500 mt-2 text-xs md:text-sm max-w-md mx-auto">
                Fill out the inquiry form below, and our corporate partnership manager will reach out with a custom proposal.
              </p>
            </div>

            <form onSubmit={handleSubmit} className="space-y-5">
              
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                <div className="space-y-1">
                  <label className="block text-xs font-black uppercase text-slate-500 tracking-wider">Company Name *</label>
                  <input
                    type="text"
                    required
                    value={form.companyName}
                    onChange={e => setForm({...form, companyName: e.target.value})}
                    placeholder="e.g. Sana Pathology Labs Inc"
                    className="w-full px-4 py-3 border-2 border-slate-200 rounded-xl text-sm focus:outline-none focus:border-[#1D9E75] bg-slate-50/50"
                  />
                </div>
                <div className="space-y-1">
                  <label className="block text-xs font-black uppercase text-slate-500 tracking-wider">Contact Person *</label>
                  <input
                    type="text"
                    required
                    value={form.contactPerson}
                    onChange={e => setForm({...form, contactPerson: e.target.value})}
                    placeholder="e.g. Mohd. Altamash"
                    className="w-full px-4 py-3 border-2 border-slate-200 rounded-xl text-sm focus:outline-none focus:border-[#1D9E75] bg-slate-50/50"
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                <div className="space-y-1">
                  <label className="block text-xs font-black uppercase text-slate-500 tracking-wider">Mobile Number *</label>
                  <input
                    type="tel"
                    required
                    maxLength={10}
                    pattern="[0-9]{10}"
                    value={form.mobile}
                    onChange={e => setForm({...form, mobile: e.target.value.replace(/\D/g, '')})}
                    placeholder="10-digit number"
                    className="w-full px-4 py-3 border-2 border-slate-200 rounded-xl text-sm focus:outline-none focus:border-[#1D9E75] bg-slate-50/50"
                  />
                </div>
                <div className="space-y-1">
                  <label className="block text-xs font-black uppercase text-slate-500 tracking-wider">No. of Employees *</label>
                  <input
                    type="number"
                    required
                    min={1}
                    value={form.noOfEmployees}
                    onChange={e => setForm({...form, noOfEmployees: e.target.value})}
                    placeholder="e.g. 50"
                    className="w-full px-4 py-3 border-2 border-slate-200 rounded-xl text-sm focus:outline-none focus:border-[#1D9E75] bg-slate-50/50"
                  />
                </div>
              </div>

              <div className="space-y-1">
                <label className="block text-xs font-black uppercase text-slate-500 tracking-wider">Preferred Checkup Date *</label>
                <input
                  type="date"
                  required
                  value={form.preferredDate}
                  onChange={e => setForm({...form, preferredDate: e.target.value})}
                  className="w-full px-4 py-3 border-2 border-slate-200 rounded-xl text-sm focus:outline-none focus:border-[#1D9E75] bg-slate-50/50"
                />
              </div>

              <div className="space-y-1">
                <label className="block text-xs font-black uppercase text-slate-500 tracking-wider">Additional Requirements (Optional)</label>
                <textarea
                  value={form.notes}
                  onChange={e => setForm({...form, notes: e.target.value})}
                  placeholder="Specify any custom tests required, multiple site camps, etc."
                  rows={4}
                  className="w-full px-4 py-3 border-2 border-slate-200 rounded-xl text-sm focus:outline-none focus:border-[#1D9E75] bg-slate-50/50"
                />
              </div>

              {success && (
                <div className="bg-emerald-50 text-emerald-800 border border-emerald-200 rounded-2xl p-4 text-sm font-bold text-center animate-fade-in">
                  {success}
                </div>
              )}

              {error && (
                <div className="bg-red-50 text-red-800 border border-red-200 rounded-2xl p-4 text-sm font-bold text-center animate-fade-in">
                  {error}
                </div>
              )}

              <button
                type="submit"
                disabled={loading}
                className="w-full bg-[#1D9E75] hover:bg-[#1D9E75]/95 text-white py-4 rounded-2xl font-bold text-sm transition-all flex items-center justify-center gap-2 shadow-lg shadow-[#1D9E75]/20 hover:shadow-xl active:scale-[0.98] disabled:opacity-75"
              >
                {loading ? <Loader type="button" className="text-white" /> : <Send size={16} />}
                {loading ? 'Submitting Request...' : 'Submit B2B Inquiry'}
              </button>

            </form>
          </div>
        </section>

      </div>
    </PublicLayout>
  );
};

export default Corporate;

