  const [expandedPkg, setExpandedPkg] = useState(null);

  // Modal
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(EMPTY_FORM);
  const [selectedTestIds, setSelectedTestIds] = useState([]);
  const [testSearch, setTestSearch] = useState('');
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  const fetchPackages = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetch('/api/packages', { headers });
      const data = await res.json();
      if (Array.isArray(data)) setPackages(data);
    } catch (err) { console.error(err); }
    setLoading(false);
  }, []);

  const fetchTests = useCallback(async () => {
    try {
      const res = await fetch('/api/tests', { headers });
      const data = await res.json();
      if (Array.isArray(data)) setAllTests(data);
    } catch (err) { console.error(err); }
  }, []);

  useEffect(() => {
    fetchPackages();
    fetchTests();
  }, [fetchPackages, fetchTests]);

  const openAdd = () => {
    setEditingId(null);
    setForm(EMPTY_FORM);
    setSelectedTestIds([]);
    setTestSearch('');
    setError('');
    setIsModalOpen(true);
  };

  const openEdit = (pkg) => {
    setEditingId(pkg.id);
    setForm({ name: pkg.name, code: pkg.code, description: pkg.description || '', price: pkg.price, isActive: pkg.isActive });
    setSelectedTestIds(pkg.items.map(it => it.testId));
    setTestSearch('');
    setError('');
    setIsModalOpen(true);
  };

  const closeModal = () => { setIsModalOpen(false); setEditingId(null); setError(''); };

  const toggleTest = (testId) => {
    setSelectedTestIds(prev =>
      prev.includes(testId) ? prev.filter(id => id !== testId) : [...prev, testId]
    );
  };

  // Auto-calc recommended price (sum of selected tests) for reference
  const recommendedPrice = allTests
    .filter(t => selectedTestIds.includes(t.id))
    .reduce((sum, t) => sum + t.price, 0);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (selectedTestIds.length === 0) { setError('Please select at least one test.'); return; }
    setSaving(true); setError('');
    try {
      const url = editingId ? `/api/packages/${editingId}` : '/api/packages';
      const method = editingId ? 'PUT' : 'POST';
      const res = await fetch(url, {
        method,
        headers,
        body: JSON.stringify({ ...form, price: parseFloat(form.price), testIds: selectedTestIds }),
      });
      const data = await res.json();
      if (!res.ok) { setError(data.message || 'Failed to save package'); return; }
      closeModal();
      fetchPackages();
    } catch (err) {
      setError('An unexpected error occurred.');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id, name) => {
    if (!window.confirm(`Delete package "${name}"? This cannot be undone.`)) return;
    try {
      await fetch(`/api/packages/${id}`, { method: 'DELETE', headers });
      fetchPackages();
    } catch (err) { console.error(err); }
  };

  const handleToggleActive = async (pkg) => {
    try {
      await fetch(`/api/packages/${pkg.id}`, {
        method: 'PUT',
        headers,
        body: JSON.stringify({ isActive: !pkg.isActive }),
      });
      fetchPackages();
    } catch (err) { console.error(err); }
  };

  const filteredPackages = packages.filter(p =>
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.code.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredTests = allTests.filter(t =>
    t.testName.toLowerCase().includes(testSearch.toLowerCase()) ||
    t.testCode.toLowerCase().includes(testSearch.toLowerCase())
  );

  return (
    <Layout>
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-extrabold text-[#00488d] uppercase tracking-wide flex items-center gap-2">
            <Package className="w-6 h-6" /> Health Checkup Packages
          </h1>
          <p className="text-sm text-gray-500 mt-1">
            Bundle multiple tests into packages with combo pricing — {packages.length} packages configured
          </p>
        </div>
        <button
          onClick={openAdd}
          className="flex items-center gap-2 bg-[#00488d] hover:bg-blue-800 text-white px-5 py-2.5 rounded-lg font-bold text-sm transition-colors shadow-sm"
        >
          <Plus className="w-4 h-4" /> Add Package
        </button>
      </div>

      {/* Search */}
      <div className="bg-white rounded-lg border border-gray-200 p-3 mb-4 shadow-sm flex items-center gap-3">
        <Search className="w-4 h-4 text-gray-400 shrink-0" />
        <input
          type="text"
          value={searchTerm}
          onChange={e => setSearchTerm(e.target.value)}
          placeholder="Search packages by name or code..."
          className="flex-1 text-sm focus:outline-none"
        />
        <span className="text-xs text-gray-400 font-medium">{filteredPackages.length} found</span>
      </div>

      {/* Package Cards */}
      {loading ? (
        <div className="py-16 text-center">
          <div className="w-8 h-8 border-4 border-[#00488d] border-t-transparent rounded-full animate-spin mx-auto" />
        </div>
      ) : filteredPackages.length === 0 ? (
        <div className="py-16 text-center bg-white rounded-lg border border-gray-200 shadow-sm">
          <Package className="w-12 h-12 text-gray-200 mx-auto mb-3" />
          <p className="text-gray-500 font-medium">No packages yet</p>
          <p className="text-sm text-gray-400 mt-1">Create your first health checkup package to bundle tests together</p>
          <button onClick={openAdd} className="mt-4 bg-[#00488d] text-white px-5 py-2 rounded-lg text-sm font-bold hover:bg-blue-800 transition-colors">
            <Plus className="w-4 h-4 inline mr-1" /> Create Package
          </button>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
          {filteredPackages.map(pkg => {
            const isExpanded = expandedPkg === pkg.id;
            const totalTestsPrice = pkg.items.reduce((s, it) => s + (it.test?.price || 0), 0);
            const savings = totalTestsPrice - pkg.price;
            return (
              <div key={pkg.id} className={`bg-white rounded-xl border shadow-sm overflow-hidden transition-all ${pkg.isActive ? 'border-gray-200' : 'border-gray-100 opacity-70'}`}>
                {/* Card Header */}
                <div className="px-5 py-4 flex items-start justify-between gap-3">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <h3 className="text-base font-extrabold text-slate-800 truncate">{pkg.name}</h3>
                      <span className="text-[10px] font-black px-2 py-0.5 bg-[#00488d]/10 text-[#00488d] rounded-full font-mono">{pkg.code}</span>
                      {!pkg.isActive && <span className="text-[10px] font-black px-2 py-0.5 bg-red-100 text-red-600 rounded-full">INACTIVE</span>}
                    </div>
                    {pkg.description && <p className="text-xs text-gray-500 mt-1 line-clamp-2">{pkg.description}</p>}
                    <div className="flex items-center gap-4 mt-2">
                      <div className="flex items-center gap-1">
                        <IndianRupee className="w-4 h-4 text-[#085041]" />
                        <span className="text-lg font-black text-[#085041]">{pkg.price}</span>
                        {savings > 0 && (
                          <span className="text-xs font-bold text-amber-600 bg-amber-50 px-2 py-0.5 rounded-full ml-1">
                            Save ₹{savings}
                          </span>
                        )}
                      </div>
                      <div className="flex items-center gap-1 text-xs text-gray-400 font-medium">
                        <FlaskConical className="w-3.5 h-3.5" />
                        {pkg.items.length} tests
                        {totalTestsPrice > 0 && (
                          <span className="line-through text-gray-300 ml-1">₹{totalTestsPrice}</span>
                        )}
                      </div>
                    </div>
                  </div>

                  {/* Actions */}
                  <div className="flex items-center gap-1.5 shrink-0">
                    <button
                      onClick={() => handleToggleActive(pkg)}
                      className={`p-1.5 rounded-lg transition-colors ${pkg.isActive ? 'text-green-600 hover:bg-green-50' : 'text-gray-400 hover:bg-gray-100'}`}
                      title={pkg.isActive ? 'Deactivate' : 'Activate'}
                    >
                      {pkg.isActive ? <ToggleRight className="w-5 h-5" /> : <ToggleLeft className="w-5 h-5" />}
                    </button>
                    <button onClick={() => openEdit(pkg)} className="p-1.5 rounded-lg text-[#00488d] hover:bg-blue-50 transition-colors" title="Edit">
                      <Edit2 className="w-4 h-4" />
                    </button>
                    <button onClick={() => handleDelete(pkg.id, pkg.name)} className="p-1.5 rounded-lg text-red-500 hover:bg-red-50 transition-colors" title="Delete">
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </div>

                {/* Expand/Collapse Tests */}
                <button
                  onClick={() => setExpandedPkg(isExpanded ? null : pkg.id)}
                  className="w-full px-5 py-2 bg-gray-50 border-t border-gray-100 flex items-center justify-between text-xs font-bold text-gray-500 hover:bg-gray-100 transition-colors"
                >
                  <span>View included tests</span>
                  {isExpanded ? <ChevronUp className="w-3.5 h-3.5" /> : <ChevronDown className="w-3.5 h-3.5" />}
                </button>

                {isExpanded && (
                  <div className="px-5 py-3 border-t border-gray-100 bg-gray-50/50">
                    <div className="flex flex-wrap gap-2">
                      {pkg.items.map(it => (
                        <div key={it.id} className="flex items-center gap-1.5 bg-white border border-gray-200 px-2.5 py-1 rounded-full text-xs font-medium text-gray-700">
                          <Tag className="w-3 h-3 text-[#00488d]" />
                          {it.test?.testName || 'Unknown'}
                          <span className="text-gray-400">₹{it.test?.price}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* Add/Edit Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl max-h-[90vh] flex flex-col">
            <div className="flex justify-between items-center px-6 py-4 border-b border-gray-200 shrink-0">
              <h2 className="text-lg font-extrabold text-[#00488d]">
                {editingId ? 'Edit Package' : 'New Health Checkup Package'}
              </h2>
              <button onClick={closeModal} className="text-gray-400 hover:text-gray-600">
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="overflow-y-auto flex-1 p-6 space-y-5">
              {/* Package Info */}
              <div className="grid grid-cols-2 gap-4">
                <div className="col-span-2">
                  <label className="block text-xs font-bold text-gray-600 uppercase mb-1">Package Name *</label>
                  <input required value={form.name} onChange={e => setForm({...form, name: e.target.value})}
                    placeholder="e.g. Full Body Checkup"
                    className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-[#00488d]" />
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-600 uppercase mb-1">Package Code *</label>
                  <input required value={form.code} onChange={e => setForm({...form, code: e.target.value.toUpperCase()})}
                    placeholder="e.g. PKG-FULL"
                    className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm font-mono focus:outline-none focus:border-[#00488d]" />
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-600 uppercase mb-1">
                    Package Price (₹) *
                    {recommendedPrice > 0 && (
                      <span className="ml-2 text-amber-600 font-normal normal-case">
                        (Individual total: ₹{recommendedPrice})
                      </span>
                    )}
                  </label>
                  <input required type="number" min="0" step="0.01" value={form.price}
                    onChange={e => setForm({...form, price: e.target.value})}
                    className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-[#00488d]" />
                </div>
                <div className="col-span-2">
                  <label className="block text-xs font-bold text-gray-600 uppercase mb-1">Description</label>
                  <textarea value={form.description} onChange={e => setForm({...form, description: e.target.value})}
                    rows={2} placeholder="Brief description of what this package covers..."
                    className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-[#00488d] resize-none" />
                </div>
              </div>

              {/* Test Selection */}
              <div>
                <label className="block text-xs font-bold text-gray-600 uppercase mb-2">
                  Select Tests *
                  {selectedTestIds.length > 0 && (
                    <span className="ml-2 bg-[#00488d] text-white px-2 py-0.5 rounded-full font-bold normal-case text-[10px]">
                      {selectedTestIds.length} selected
                    </span>
                  )}
                </label>
                <div className="relative mb-2">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                  <input
                    type="text"
                    value={testSearch}
                    onChange={e => setTestSearch(e.target.value)}
                    placeholder="Filter tests..."
                    className="w-full pl-9 pr-3 py-2 border border-gray-200 rounded-lg text-sm focus:outline-none focus:border-[#00488d]"
                  />
                </div>
                <div className="border border-gray-200 rounded-lg h-52 overflow-y-auto divide-y divide-gray-50">
                  {filteredTests.map(t => {
                    const isSelected = selectedTestIds.includes(t.id);
                    return (
                      <label key={t.id}
                        className={`flex items-center gap-3 px-3 py-2 cursor-pointer transition-colors select-none ${isSelected ? 'bg-[#00488d]/5' : 'hover:bg-gray-50'}`}
                      >
                        <div className={`w-4 h-4 rounded border-2 flex items-center justify-center shrink-0 transition-colors ${isSelected ? 'bg-[#00488d] border-[#00488d]' : 'border-gray-300'}`}
                          onClick={() => toggleTest(t.id)}>
                          {isSelected && <Check className="w-2.5 h-2.5 text-white" />}
                        </div>
                        <input type="checkbox" className="sr-only" checked={isSelected} onChange={() => toggleTest(t.id)} />
                        <div className="flex-1 min-w-0">
                          <p className="text-xs font-bold text-slate-800 truncate">{t.testName}</p>
                          <p className="text-[10px] text-gray-400 font-mono">{t.testCode} · {t.category?.name}</p>
                        </div>
                        <span className="text-xs font-bold text-[#085041] shrink-0">₹{t.price}</span>
                      </label>
                    );
                  })}
                </div>
              </div>

              {error && (
                <div className="flex items-center gap-2 bg-red-50 border border-red-200 text-red-700 px-4 py-2.5 rounded-lg text-sm">
                  <AlertCircle className="w-4 h-4 shrink-0" /> {error}
                </div>
              )}

              <div className="flex justify-end gap-3 pt-2">
                <button type="button" onClick={closeModal} className="px-5 py-2.5 border border-gray-300 rounded-lg text-sm font-bold text-gray-700 hover:bg-gray-50 transition-colors">
                  Cancel
                </button>
                <button type="submit" disabled={saving}
                  className="px-5 py-2.5 bg-[#00488d] text-white rounded-lg text-sm font-bold hover:bg-blue-800 transition-colors disabled:opacity-60">
                  {saving ? 'Saving...' : editingId ? 'Update Package' : 'Create Package'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default Packages;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useLanguage } from '../context/LanguageContext';
import { HEALTH_PACKAGES_DATA, TESTS_DATA } from '../data/testsData';
import {
  Package, CheckCircle2, Clock, ShieldCheck, Award, Heart,
  ArrowRight, Info, Sparkles, TrendingUp, BadgePercent
} from 'lucide-react';
import PublicHomeHeader from '../components/PublicHomeHeader';
import EmergencyWidget from '../components/EmergencyWidget';
import LiveChatWidget from '../components/LiveChatWidget';
import PackageCard from '../components/PackageCard';
import PackageDetailsModal from '../components/PackageDetailsModal';

const PackagesPage = () => {
  const { t, language } = useLanguage();
  const navigate = useNavigate();
  const [selectedPackageDetails, setSelectedPackageDetails] = useState(null);
  const [cartItems, setCartItems] = useState(() => {
    try { return JSON.parse(localStorage.getItem('sana_cart')) || []; } catch { return []; }
  });

  useEffect(() => { window.scrollTo(0, 0); }, []);

  const getTestDetails = (testCode) => {
    const found = TESTS_DATA.find(t => t.code === testCode || t.testCode === testCode);
    return found || { testName: testCode, price: 0, category: { name: 'General' } };
  };

  const handleAddToCart = (pkg) => {
    const exists = cartItems.some(item => item.testCode === pkg.code);
    let newCart;
    if (exists) {
      newCart = cartItems.filter(item => item.testCode !== pkg.code);
    } else {
      newCart = [...cartItems, {
        name: pkg.name, price: pkg.price, testCode: pkg.code, isPackage: true
      }];
    }
    setCartItems(newCart);
    localStorage.setItem('sana_cart', JSON.stringify(newCart));
  };

  const handleBookNow = (pkg) => {
    if (pkg) {
      const exists = cartItems.some(item => item.testCode === pkg.code);
      if (!exists) {
        const newCart = [...cartItems, {
          name: pkg.name, price: pkg.price, testCode: pkg.code, isPackage: true
        }];
        setCartItems(newCart);
        localStorage.setItem('sana_cart', JSON.stringify(newCart));
      }
    }
    navigate('/book-online');
    window.scrollTo(0, 0);
  };

  return (
    <div className="min-h-screen bg-bg font-sans text-slate-800">
      <PublicHomeHeader cartCount={cartItems.length} />

      {/* Hero */}
      <section className="relative pt-24 pb-28 overflow-hidden bg-gradient-to-br from-[#063b30] via-[#085041] to-[#0b6b55]">
        <div className="absolute top-[-20%] left-[-10%] w-[500px] h-[500px] bg-emerald-400/10 rounded-full blur-[120px]"></div>
        <div className="absolute bottom-[-20%] right-[-10%] w-[400px] h-[400px] bg-teal-400/10 rounded-full blur-[100px]"></div>
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10 text-center">
          <div className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-white/10 text-emerald-200 text-xs font-bold tracking-wider uppercase mb-6 backdrop-blur-md border border-white/20">
            <Sparkles size={14} className="text-[#F1C40F]" />
            Curated Wellness
          </div>
          <h1 className="text-4xl md:text-6xl font-heading font-black text-white leading-tight mb-4">
            {t('popularPackages')}
          </h1>
          <p className="text-lg md:text-xl text-emerald-100/80 max-w-2xl mx-auto font-medium">
            {t('packagesSub')}
          </p>
        </div>
      </section>

      {/* Packages Grid */}
      <section className="py-20 px-4 sm:px-6 lg:px-8 -mt-12 relative z-20">
        <div className="max-w-7xl mx-auto">
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            {HEALTH_PACKAGES_DATA.map((pkg) => (
              <PackageCard 
                key={pkg.code} 
                pkg={pkg} 
                isAdded={cartItems.some(item => item.testCode === pkg.code)}
                onAdd={handleAddToCart}
                onKnowMore={(p) => setSelectedPackageDetails(p)}
                onBookNow={handleBookNow}
                onWhatsApp={(msg) => window.open(`https://wa.me/916396786939?text=${encodeURIComponent(msg)}`, '_blank')}
              />
            ))}
          </div>

          {/* Cart Summary */}
          {cartItems.length > 0 && (
            <div className="mt-12 bg-white rounded-3xl border border-slate-100 shadow-lg p-6 md:p-8">
              <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
                <div>
                  <h3 className="text-lg font-black text-slate-800">Your Selection</h3>
                  <p className="text-sm text-slate-500 font-semibold">
                    {cartItems.length} item{cartItems.length > 1 ? 's' : ''} in cart
                  </p>
                </div>
                <div className="flex items-center gap-4">
                  <div className="text-right">
                    <p className="text-xs text-slate-400 font-bold">Total</p>
                    <p className="text-2xl font-black text-primary">
                      ₹{cartItems.reduce((sum, item) => sum + item.price, 0)}
                    </p>
                  </div>
                  <button
                    onClick={handleBookNow}
                    className="bg-gradient-to-r from-primary to-primary-light text-white px-8 py-3.5 rounded-2xl font-bold text-sm shadow-lg shadow-primary/20 hover:shadow-xl hover:shadow-primary/30 transition-all hover:-translate-y-0.5 active:scale-[0.98]"
                  >
                    Book Now <ArrowRight size={16} className="inline ml-1" />
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>
      </section>

      {/* Benefit Strip */}
      <section className="py-16 bg-primary-pale/30 border-y border-emerald-100/50 px-4 sm:px-6 lg:px-8">
        <div className="max-w-7xl mx-auto">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
            {[
              { icon: ShieldCheck, label: 'NABL Accredited Lab', sub: 'ISO 15189 Standards' },
              { icon: Clock, label: '6-12 Hour TAT', sub: 'Fast Report Delivery' },
              { icon: Heart, label: 'Free Home Collection', sub: 'Within City Limits' },
              { icon: TrendingUp, label: 'Certified Pathologists', sub: 'MD, DNB Qualified' },
            ].map((item) => {
              const Icon = item.icon;
              return (
                <div key={item.label} className="text-center p-6">
                  <div className="w-12 h-12 rounded-xl bg-primary/10 flex items-center justify-center mx-auto mb-3">
                    <Icon className="w-6 h-6 text-primary" />
                  </div>
                  <h4 className="font-bold text-slate-800 text-sm">{item.label}</h4>
                  <p className="text-xs text-slate-500 font-semibold mt-1">{item.sub}</p>
                </div>
              );
            })}
          </div>
        </div>
      </section>

      {/* Footer */}
      <footer className="bg-[#085041] pt-16 pb-8 px-4 sm:px-6 lg:px-8 text-primary-pale">
        <div className="max-w-7xl mx-auto text-center border-t border-white/10 pt-8 text-sm opacity-60">
          {t('copyright')}
        </div>
      </footer>

      <EmergencyWidget />
      <LiveChatWidget />

      <PackageDetailsModal 
        pkg={selectedPackageDetails}
        onClose={() => setSelectedPackageDetails(null)}
        onBookNow={(p) => {
          setSelectedPackageDetails(null);
          handleBookNow(p);
        }}
        isAdded={selectedPackageDetails ? cartItems.some(item => item.testCode === selectedPackageDetails.code) : false}
      />
    </div>
  );
};

export default PackagesPage;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import PublicLayout from '../components/PublicLayout';
import { HEALTH_PACKAGES_DATA, TESTS_DATA } from '../data/testsData';
import {
  Package, Check, ShoppingCart, Plus, Info,
  TrendingDown, Award, Sparkles,
  ChevronDown, ChevronUp, MessageCircle, ArrowRight
} from 'lucide-react';
import PackageCard from '../components/PackageCard';
import PackageDetailsModal from '../components/PackageDetailsModal';

const PHONE = '916396786939';

const getTestName = (code) => {
  const test = TESTS_DATA.find(t => t.code === code);
  return test ? test.testName : code;
};

const PackagesPublic = () => {
  const [cart, setCart] = useState(() => {
    try {
      const saved = localStorage.getItem('sana_cart');
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  const [openFaq, setOpenFaq] = useState(null);
  const [customTests, setCustomTests] = useState({});
  const [selectedPackageDetails, setSelectedPackageDetails] = useState(null);

  useEffect(() => {
    localStorage.setItem('sana_cart', JSON.stringify(cart));
  }, [cart]);

  useEffect(() => {
    try {
      if (window.gtag) {
        window.gtag('event', 'page_view', {
          page_title: 'Health Packages',
          page_location: window.location.href,
          page_path: '/packages-public'
        });
      }
    } catch {}
  }, []);

  const fireGA = useCallback((action, label) => {
    try {
      if (window.gtag) {
        window.gtag('event', action, { event_label: label });
      }
    } catch {}
  }, []);

  const addToCart = useCallback((item) => {
    setCart(prev => [...prev, item]);
    fireGA('add_to_cart', item.name);
  }, [fireGA]);

  const isInCart = useCallback((testCode) => {
    return cart.some(item => item.testCode === testCode);
  }, [cart]);

  const handlePackageToggle = (pkg) => {
    if (isInCart(pkg.code)) {
      setCart(prev => prev.filter(item => item.testCode !== pkg.code));
      fireGA('remove_from_cart', pkg.name);
    } else {
      addToCart({
        name: pkg.name,
        price: pkg.price,
        testCode: pkg.code,
        isPackage: true
      });
    }
  };

  const handleBookNow = (pkg) => {
    if (!isInCart(pkg.code)) {
      addToCart({
        name: pkg.name,
        price: pkg.price,
        testCode: pkg.code,
        isPackage: true
      });
    }
    navigate('/book-online');
    window.scrollTo(0, 0);
  };

  const toggleCustomTest = (code) => {
    setCustomTests(prev => ({ ...prev, [code]: !prev[code] }));
  };

  const addCustomToCart = () => {
    const selected = TESTS_DATA.filter(t => customTests[t.code]);
    if (selected.length === 0) return;
    const items = selected.map(t => ({
      name: t.testName,
      price: t.price,
      testCode: t.code,
      isPackage: false
    }));
    setCart(prev => [...prev, ...items]);
    fireGA('add_custom_package', `${items.length} tests`);
    setCustomTests({});
  };

  const customTotal = useMemo(() => {
    return TESTS_DATA.filter(t => customTests[t.code]).reduce((sum, t) => sum + t.price, 0);
  }, [customTests]);

  const customCount = useMemo(() => {
    return Object.values(customTests).filter(Boolean).length;
  }, [customTests]);

  const cartTotal = useMemo(() => {
    return cart.reduce((sum, item) => sum + item.price, 0);
  }, [cart]);

  const displayTests = useMemo(() => TESTS_DATA.slice(0, 18), []);

  const handleWhatsApp = (msg) => {
    window.open(`https://wa.me/${PHONE}?text=${encodeURIComponent(msg)}`, '_blank');
    fireGA('whatsapp_click', msg.slice(0, 50));
  };

  const faqs = [
    {
      q: 'Health packages mein kya kya tests included hain?',
      a: 'Har package ki apni test list hoti hai. Basic Care Package mein CBC, LFT, KFT, FBS aur Lipid Profile shamil hain. Aap neeche diye cards mein poori list dekh sakte hain.'
    },
    {
      q: 'Kya mujhe test se pehle fasting (upwas) karna hoga?',
      a: 'Ye test par nirbhar karta hai. FBS aur Lipid Profile jaise tests ke liye 8-12 ghante fasting aavashyak hai. Kuch tests (jaise CBC, HbA1c) ke liye fasting nahi chahiye. Booking ke waqt hum aapko guide karenge.'
    },
    {
      q: 'Ghar se sample collection kaise hota hai?',
      a: 'Booking confirm hone ke baad, humara certified phlebotomist aapke door step par aata hai aur safe tarike se sample collect karta hai. Home collection ₹500 se upar ki booking par bilkul free hai.'
    },
    {
      q: 'Kya main apna custom package bana sakta hoon?',
      a: 'Bilkul! "Custom Package Banao" section mein jayein, neeche diye gaye tests mein se apni need ke tests select karein, aur "Add to Cart" par click karein. Aap utne tests select kar sakte hain jitne chaahein.'
    },
    {
      q: 'Payment ke kya options hain?',
      a: 'Aap Cash, UPI (Google Pay, PhonePe, Paytm), ya Credit/Debit card se payment kar sakte hain. Payment collection ke time par hoti hai ya aap online bhi advance payment kar sakte hain.'
    }
  ];

  const badgeStyle = (badge) => {
    const map = {
      'Popular': 'bg-emerald-100 text-emerald-800 border-emerald-200',
      'Best Value': 'bg-amber-100 text-amber-800 border-amber-200',
      'Recommended': 'bg-blue-100 text-blue-800 border-blue-200'
    };
    return map[badge] || 'bg-gray-100 text-gray-800 border-gray-200';
  };

  const badgeIcon = (badge) => {
    const map = {
      'Popular': <TrendingDown className="w-3.5 h-3.5" />,
      'Best Value': <Award className="w-3.5 h-3.5" />,
      'Recommended': <Sparkles className="w-3.5 h-3.5" />
    };
    return map[badge] || <Info className="w-3.5 h-3.5" />;
  };

  return (
    <PublicLayout>
      {/* Hero Banner */}
      <section className="relative overflow-hidden bg-gradient-to-br from-[#085041] to-[#0F6E56] px-4 sm:px-6 lg:px-8 py-16 md:py-24 lg:py-32">
        <div className="absolute top-10 left-10 w-64 h-64 bg-white/5 rounded-full blur-3xl pointer-events-none"></div>
        <div className="absolute bottom-10 right-10 w-80 h-80 bg-emerald-400/10 rounded-full blur-3xl pointer-events-none"></div>
        <div className="absolute top-1/3 right-1/4 w-4 h-4 bg-emerald-300/30 rounded-full blur-[2px] animate-pulse pointer-events-none"></div>
        <div className="absolute bottom-1/4 left-1/3 w-3 h-3 bg-yellow-300/20 rounded-full blur-[1px] animate-pulse pointer-events-none" style={{ animationDelay: '1.5s' }}></div>

        <div className="relative z-10 max-w-7xl mx-auto text-center">
          <div className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-white/10 text-emerald-200 text-xs font-bold tracking-wider uppercase mb-6 backdrop-blur-md border border-white/20">
            <Sparkles className="w-4 h-4 text-yellow-300" />
            Save Up to 60%
          </div>
          <h1 className="text-3xl sm:text-4xl md:text-5xl lg:text-6xl font-black text-white leading-tight mb-4 drop-shadow-lg">
            Health Packages — Complete Body Checkup at Best Price
          </h1>
          <p className="text-base md:text-lg text-emerald-100/90 max-w-2xl mx-auto mb-8 font-medium drop-shadow-md">
            Sambhal ka sabse affordable health package. Ghar baithe free collection.
          </p>
          <div className="flex flex-col sm:flex-row items-center gap-4 justify-center">
            <a
              href="#packages"
              className="inline-flex items-center gap-2 bg-white text-[#085041] hover:bg-emerald-50 px-8 py-3.5 rounded-2xl font-bold text-sm shadow-lg shadow-black/10 transition-all hover:-translate-y-0.5 active:scale-[0.98]"
            >
              <Package className="w-5 h-5" />
              View Packages
            </a>
            <button
              onClick={() => handleWhatsApp('Hi Sana Pathology, I want to know about your health packages. Please share details.')}
              className="inline-flex items-center gap-2 bg-[#25D366] text-white hover:bg-[#128C7E] px-8 py-3.5 rounded-2xl font-bold text-sm shadow-lg shadow-green-600/20 transition-all hover:-translate-y-0.5 active:scale-[0.98]"
            >
              <MessageCircle className="w-5 h-5" />
              WhatsApp to Book
            </button>
          </div>
        </div>
      </section>

      {/* Packages Grid */}
      <section id="packages" className="py-16 md:py-20 px-4 sm:px-6 lg:px-8 bg-gray-50">
        <div className="max-w-7xl mx-auto">
          <div className="text-center mb-12">
            <span className="text-xs font-black tracking-widest text-[#1D9E75] uppercase bg-emerald-50 px-4 py-1.5 rounded-full">
              Health Packages
            </span>
            <h2 className="text-3xl md:text-4xl font-black text-gray-900 mt-4 mb-2">
              Choose Your Health Package
            </h2>
            <p className="text-gray-500 max-w-xl mx-auto">
              Select from our curated health packages designed for every need
            </p>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            {HEALTH_PACKAGES_DATA.map((pkg) => (
              <PackageCard 
                key={pkg.code} 
                pkg={pkg} 
                isAdded={isInCart(pkg.code)}
                onAdd={handlePackageToggle}
                onKnowMore={(p) => setSelectedPackageDetails(p)}
                onBookNow={handleBookNow}
                onWhatsApp={(msg) => handleWhatsApp(msg)}
              />
            ))}
          </div>
        </div>
      </section>

      {/* Custom Package Builder */}
      <section className="py-16 md:py-20 px-4 sm:px-6 lg:px-8 bg-white">
        <div className="max-w-7xl mx-auto">
          <div className="text-center mb-10">
            <span className="text-xs font-black tracking-widest text-[#1D9E75] uppercase bg-emerald-50 px-4 py-1.5 rounded-full">
              Custom Package
            </span>
            <h2 className="text-3xl md:text-4xl font-black text-gray-900 mt-4 mb-2">
              Custom Package Banao — Sirf apne liye
            </h2>
            <p className="text-gray-500 max-w-xl mx-auto">
              Apni need ke tests select karein aur apna khud ka package banayein
            </p>
          </div>

          <div className="max-w-4xl mx-auto">
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3 mb-8">
              {displayTests.map((test) => {
                const selected = !!customTests[test.code];
                return (
                  <button
                    key={test.code}
                    onClick={() => toggleCustomTest(test.code)}
                    className={`flex items-center gap-3 p-3.5 rounded-2xl border-2 text-left transition-all ${
                      selected
                        ? 'border-[#1D9E75] bg-emerald-50 shadow-sm'
                        : 'border-gray-200 bg-white hover:border-emerald-200 hover:bg-emerald-50/30'
                    }`}
                  >
                    <div className={`w-5 h-5 rounded-md border-2 flex items-center justify-center shrink-0 transition-all ${
                      selected
                        ? 'bg-[#1D9E75] border-[#1D9E75]'
                        : 'border-gray-300 bg-white'
                    }`}>
                      {selected && <Check className="w-3.5 h-3.5 text-white stroke-[3]" />}
                    </div>
                    <div className="min-w-0">
                      <span className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider">{test.code}</span>
                      <span className="block text-sm font-semibold text-gray-800 truncate">{test.testName}</span>
                      <span className="text-xs font-bold text-[#1D9E75]">₹{test.price}</span>
                    </div>
                  </button>
                );
              })}
            </div>

            {customCount > 0 && (
              <div className="bg-gray-50 rounded-3xl p-6 border border-gray-200 transition-all">
                <div className="flex items-center justify-between mb-4">
                  <div className="flex items-center gap-2">
                    <ShoppingCart className="w-5 h-5 text-[#1D9E75]" />
                    <span className="font-bold text-gray-800">
                      Selected Tests: {customCount}
                    </span>
                  </div>
                  <span className="text-2xl font-black text-[#1D9E75]">
                    ₹{customTotal}
                  </span>
                </div>
                <button
                  onClick={addCustomToCart}
                  className="w-full bg-[#1D9E75] text-white py-3.5 rounded-2xl font-bold text-sm hover:bg-[#187a5a] transition-all flex items-center justify-center gap-2 shadow-lg shadow-emerald-200 active:scale-[0.98]"
                >
                  <Plus className="w-5 h-5" />
                  Add to Cart — ₹{customTotal}
                </button>
              </div>
            )}
          </div>
        </div>
      </section>

      {/* FAQ Section */}
      <section className="py-16 md:py-20 px-4 sm:px-6 lg:px-8 bg-gray-50">
        <div className="max-w-3xl mx-auto">
          <div className="text-center mb-10">
            <span className="text-xs font-black tracking-widest text-[#1D9E75] uppercase bg-emerald-50 px-4 py-1.5 rounded-full">
              FAQ
            </span>
            <h2 className="text-3xl md:text-4xl font-black text-gray-900 mt-4 mb-2">
              Frequently Asked Questions
            </h2>
          </div>

          <div className="space-y-3">
            {faqs.map((faq, idx) => (
              <div key={idx} className="bg-white rounded-2xl border border-gray-100 overflow-hidden transition-shadow hover:shadow-sm">
                <button
                  onClick={() => {
                    setOpenFaq(openFaq === idx ? null : idx);
                    fireGA('faq_toggle', faq.q.slice(0, 50));
                  }}
                  className="w-full flex items-center justify-between p-5 text-left font-bold text-gray-900 hover:bg-gray-50 transition-colors"
                >
                  <span className="text-sm md:text-base pr-4">{faq.q}</span>
                  {openFaq === idx ? (
                    <ChevronUp className="w-5 h-5 text-[#1D9E75] shrink-0" />
                  ) : (
                    <ChevronDown className="w-5 h-5 text-gray-400 shrink-0" />
                  )}
                </button>
                {openFaq === idx && (
                  <div className="px-5 pb-5 text-sm text-gray-600 leading-relaxed border-t border-gray-100 pt-4">
                    {faq.a}
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Sticky Cart Bottom Bar */}
      {cart.length > 0 && (
        <div className="fixed bottom-0 left-0 right-0 z-50 bg-white border-t border-gray-200 shadow-[0_-4px_20px_rgba(0,0,0,0.08)] px-4 py-3 md:py-4">
          <div className="max-w-7xl mx-auto flex items-center justify-between gap-4">
            <div className="flex items-center gap-3">
              <div className="relative">
                <ShoppingCart className="w-6 h-6 text-[#1D9E75]" />
                <span className="absolute -top-2 -right-2 bg-[#1D9E75] text-white text-[10px] font-bold w-5 h-5 rounded-full flex items-center justify-center">
                  {cart.length}
                </span>
              </div>
              <div>
                <p className="text-xs text-gray-500 font-medium">{cart.length} Item{cart.length !== 1 ? 's' : ''}</p>
                <p className="text-sm font-black text-gray-900">₹{cartTotal}</p>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <button
                onClick={() => handleWhatsApp(`Hi Sana Pathology, I want to book the following:\n${cart.map(i => `- ${i.name} (₹${i.price})`).join('\n')}\nTotal: ₹${cartTotal}`)}
                className="inline-flex items-center gap-1.5 bg-[#25D366] text-white px-4 py-2.5 rounded-xl font-bold text-xs hover:bg-[#128C7E] transition-all active:scale-[0.97]"
              >
                <MessageCircle className="w-4 h-4" />
                WhatsApp
              </button>
              <button
                onClick={() => {
                  window.location.href = '/#booking';
                  fireGA('book_now_click', `Cart total: ₹${cartTotal}`);
                }}
                className="inline-flex items-center gap-1.5 bg-[#1D9E75] text-white px-6 py-2.5 rounded-xl font-bold text-sm hover:bg-[#187a5a] transition-all shadow-lg shadow-emerald-200 active:scale-[0.97]"
              >
                Book Now
                <ArrowRight className="w-4 h-4" />
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Spacer for sticky bar */}
      {cart.length > 0 && <div className="h-20 md:h-24"></div>}
      <PackageDetailsModal 
        pkg={selectedPackageDetails}
        onClose={() => setSelectedPackageDetails(null)}
        onBookNow={(p) => {
          setSelectedPackageDetails(null);
          handleBookNow(p);
        }}
        isAdded={selectedPackageDetails ? isInCart(selectedPackageDetails.code) : false}
      />
    </PublicLayout>
  );
};

export default PackagesPublic;

