                    >
                      {language === 'hi' ? 'लक्षण सर्वेक्षण शुरू करें' : 'Begin Diagnosis'}
                    </button>
                  </div>
                </div>
              )}

              {/* Step 2: Interactive State Machine Question Flow */}
