  const [reportNumberInput, setReportNumberInput] = useState('');
  const [reports, setReports] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [expandedId, setExpandedId] = useState(null);
  const [statsVisible, setStatsVisible] = useState(false);
  const [tests, setTests] = useState([]);
  const [currentTip, setCurrentTip] = useState(0);
  const [openFaq, setOpenFaq] = useState(null);

  // AI Explainer State
  const [isExplaining, setIsExplaining] = useState(false);
  const [explanation, setExplanation] = useState('');
  const [explainingReportId, setExplainingReportId] = useState(null);
  const [aiLanguage, setAiLanguage] = useState(language || 'en');

  // OTP verification states
  const [otpSent, setOtpSent] = useState(false);
  const [otp, setOtp] = useState('');
  const [otpLoading, setOtpLoading] = useState(false);
  const [otpMessage, setOtpMessage] = useState('');
  const [actualMobile, setActualMobile] = useState('');
  const [token, setToken] = useState('');

  // Health Trends states
  const [trends, setTrends] = useState([]);
  const [selectedTrend, setSelectedTrend] = useState('');

  const computeTrends = (reportsList) => {
    const parameterMap = {};
    const sortedReports = [...reportsList]
      .filter(r => r.status === 'COMPLETED')
      .sort((a, b) => new Date(a.reportDate) - new Date(b.reportDate));

    sortedReports.forEach(r => {
      const dateStr = new Date(r.reportDate).toLocaleDateString('en-IN', { month: 'short', day: 'numeric', year: '2-digit' });
      r.results.forEach(res => {
        const val = parseFloat(res.resultValue);
        if (res.parameterName && !isNaN(val)) {
          const name = res.parameterName.trim();
          if (!parameterMap[name]) {
            parameterMap[name] = {
              parameterName: name,
              unit: res.unit || '',
              referenceRange: res.referenceRange || '',
              history: []
            };
          }
          parameterMap[name].history.push({
            date: dateStr,
            value: val,
            flag: res.flag || 'NORMAL'
          });
        }
      });
    });

    return Object.values(parameterMap).filter(p => p.history.length >= 2);
  };

  useEffect(() => {
    if (reports && reports.length > 0) {
      const computed = computeTrends(reports);
      setTrends(computed);
      if (computed.length > 0) {
        setSelectedTrend(computed[0].parameterName);
      } else {
        setSelectedTrend('');
      }
    } else {
      setTrends([]);
      setSelectedTrend('');
    }
  }, [reports]);

  const activeTrend = trends.find(t => t.parameterName === selectedTrend);
  const trendLineData = activeTrend ? {
    labels: activeTrend.history.map(h => h.date),
    datasets: [{
      label: `${activeTrend.parameterName} (${activeTrend.unit})`,
      data: activeTrend.history.map(h => h.value),
      borderColor: '#1D9E75',
      backgroundColor: 'rgba(29, 158, 117, 0.1)',
      fill: true,
      tension: 0.3,
      pointBackgroundColor: '#1D9E75',
      pointHoverRadius: 7,
      pointRadius: 5
    }]
  } : null;

  const chartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: { display: false },
      tooltip: {
        callbacks: {
          label: (context) => {
            const histNode = activeTrend?.history[context.dataIndex];
            return `Value: ${context.parsed.y} ${activeTrend?.unit} (${histNode?.flag || 'NORMAL'})`;
          }
        }
      }
    },
    scales: {
      y: {
        beginAtZero: false,
        grid: { color: '#f1f5f9' },
        title: { display: true, text: activeTrend?.unit || '', font: { size: 11 } }
      },
      x: { grid: { display: false } }
    }
  };

  useEffect(() => {
    const hash = window.location.hash;
    const qIndex = hash.indexOf('?');
    const params = new URLSearchParams(qIndex !== -1 ? hash.substring(qIndex) : '');
    const reportParam = params.get('reportNumber');
    const nameParam = params.get('patientName');
    const mobileParam = params.get('mobile');
    
    if (reportParam) {
      setSearchType('report');
      setReportNumberInput(reportParam);
      if (nameParam) {
        setPatientName(nameParam);
        handleDirectLookup(null, reportParam, nameParam);
      }
    } else if (mobileParam) {
      setSearchType('mobile');
      setQuery(mobileParam);
      fetchReports(mobileParam);
    }

    fetch(`${API}/public/tests`)
      .then(r => r.json())
      .then(data => {
        if (Array.isArray(data)) setTests(data.slice(0, 6));
      })
      .catch(() => {});
  }, []);

  useEffect(() => {
    if (!statsRef.current) return;
    const obs = new IntersectionObserver(
      ([entry]) => { if (entry.isIntersecting) setStatsVisible(true); },
      { threshold: 0.2 }
    );
    obs.observe(statsRef.current);
    return () => obs.disconnect();
  }, []);

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentTip(prev => (prev + 1) % HEALTH_TIPS.length);
    }, 4000);
    return () => clearInterval(timer);
  }, []);

