    if (!repNum || !patName) return;

    setLoading(true);
    setError('');
    setReports([]);
    
    try {
      const res = await fetch(`${API}/public/report-direct-lookup?reportNumber=${encodeURIComponent(repNum)}&patientName=${encodeURIComponent(patName)}`);
      const data = await res.json();
      if (!res.ok) {
        setError(data.message || 'Report not found or patient name does not match.');
      } else {
        setReports(data);
        if (data.length === 1) setExpandedId(data[0].id);
      }
    } catch (err) {
      setError('Could not connect to the server. Please try again.');
