import React, { useState, useEffect, useContext } from 'react';
import { useNavigate } from 'react-router-dom';
import Layout from '../components/Layout';
import { AuthContext } from '../context/AuthContext';
import { Plus, Search, Tag, Edit2, Trash2, ExternalLink, X } from 'lucide-react';

const Tests = () => {
  const navigate = useNavigate();
  const { user } = useContext(AuthContext);
  const [tests, setTests] = useState([]);
  const [categories, setCategories] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  
  // Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState(null);
  
  const [formData, setFormData] = useState({
    testName: '', testCode: '', sampleType: 'Blood', price: '', categoryId: '', newCategoryName: '', summary: ''
  });
  const [parameters, setParameters] = useState([
    { parameterName: '', referenceRange: '', unit: '', groupName: '', isQualitative: false }
  ]);

  useEffect(() => {
    fetchTests();
    fetchCategories();
  }, []);

  const fetchTests = async () => {
    try {
      const res = await fetch('/api/tests', {
        headers: { 'Authorization': `Bearer ${user.accessToken}` }
      });
      const data = await res.json();
      if (Array.isArray(data)) setTests(data);
    } catch (err) {
      console.error(err);
    }
  };

  const fetchCategories = async () => {
    try {
      const res = await fetch('/api/tests/categories', {
        headers: { 'Authorization': `Bearer ${user.accessToken}` }
      });
      const data = await res.json();
      if (Array.isArray(data)) setCategories(data);
    } catch (err) {
      console.error(err);
    }
  };

  const addParameterRow = () => {
    setParameters([...parameters, { parameterName: '', referenceRange: '', unit: '', groupName: '', isQualitative: false }]);
  };

  const fillWidalPreset = () => {
    setFormData(prev => ({
      ...prev,
      testName: 'WIDAL TEST (Rapid Slid Method)',
      testCode: 'WIDAL',
      sampleType: 'BLOOD',
      price: '200',
      summary: 'Widal test is a serological test for detecting antibodies against Salmonella typhi and paratyphi. A titre of 1:80 or more for O antigen and 1:160 or more for H antigen is considered clinically significant.'
    }));
    // Auto-select Immunology category if it exists
    const immunoCat = categories.find(c => c.name === 'Immunology');
    if (immunoCat) setFormData(prev => ({ ...prev, categoryId: immunoCat.id }));
    setParameters([
      { parameterName: 'S. TYPHI O', referenceRange: '', unit: '', groupName: '', isQualitative: true, titerValues: '1/20,1/40,1/80,1/160,1/320' },
      { parameterName: 'S. TYPHI H', referenceRange: '', unit: '', groupName: '', isQualitative: true, titerValues: '1/20,1/40,1/80,1/160,1/320' },
      { parameterName: 'S. PARA TYPHI A (H)', referenceRange: '', unit: '', groupName: '', isQualitative: true, titerValues: '1/20,1/40,1/80,1/160,1/320' },
      { parameterName: 'S. PARA TYPHI B (H)', referenceRange: '', unit: '', groupName: '', isQualitative: true, titerValues: '1/20,1/40,1/80,1/160,1/320' },
    ]);
  };
  const removeParameterRow = (index) => {
    const p = [...parameters];
    p.splice(index, 1);
    setParameters(p);
  };
  const updateParameter = (index, field, value) => {
    const p = [...parameters];
    p[index][field] = value;
    setParameters(p);
  };

  const getQualitativeType = (p) => {
    if (!p.isQualitative) return '';
    if (p.titerValues && p.titerValues.trim() !== '') return 'titer';
    const range = (p.referenceRange || '').toUpperCase();
    if (range.includes('NEGATIVE') || range.includes('POSITIVE')) return 'pos_neg';
    if (range.includes('REACTIVE') || range.includes('NON-REACTIVE')) return 'reactive_nonreactive';
    if (range.includes('SEEN') || range.includes('NOT-SEEN') || range.includes('NOT SEEN')) return 'seen_notseen';
    if (range.trim() !== '') return 'custom';
    return 'pos_neg';
  };

  const handleQualitativeTypeChange = (idx, type) => {
    const p = [...parameters];
    p[idx].titerValues = '';
    if (type === 'pos_neg') {
      p[idx].referenceRange = 'NEGATIVE / POSITIVE';
    } else if (type === 'reactive_nonreactive') {
      p[idx].referenceRange = 'NON-REACTIVE / REACTIVE';
    } else if (type === 'seen_notseen') {
      p[idx].referenceRange = 'NOT-SEEN / SEEN';
    } else if (type === 'titer') {
      p[idx].referenceRange = '';
      p[idx].titerValues = '1/20,1/40,1/80,1/160,1/320';
    } else if (type === 'custom') {
      p[idx].referenceRange = '';
    }
    setParameters(p);
  };

  const handleIsQualitativeToggle = (idx, checked) => {
    const p = [...parameters];
    p[idx].isQualitative = checked;
    if (checked) {
      p[idx].referenceRange = 'NEGATIVE / POSITIVE';
      p[idx].titerValues = '';
      p[idx].unit = '';
    } else {
      p[idx].referenceRange = '';
      p[idx].titerValues = '';
    }
    setParameters(p);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      let finalCategoryId = parseInt(formData.categoryId);

      if (!finalCategoryId && formData.newCategoryName) {
        const catRes = await fetch('/api/tests/categories', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${user.accessToken}` },
          body: JSON.stringify({ name: formData.newCategoryName })
        });
        const catData = await catRes.json();
        finalCategoryId = catData.id;
        fetchCategories();
      }

      if (!finalCategoryId) return alert('Please select or create a category');

      const url = editingId 
        ? `/api/tests/${editingId}` 
        : '/api/tests';
      const method = editingId ? 'PUT' : 'POST';

      const res = await fetch(url, {
        method,
        headers: { 
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${user.accessToken}` 
        },
        body: JSON.stringify({
          testName: formData.testName,
          testCode: formData.testCode,
          sampleType: formData.sampleType,
          price: parseFloat(formData.price),
          categoryId: finalCategoryId,
          summary: formData.summary || null,
          parameters: parameters.filter(p => p.parameterName.trim() !== '')
        })
      });
      if (res.ok) {
        closeModal();
        fetchTests();
      } else {
        alert('Failed to save test');
      }
    } catch (err) {
      console.error(err);
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm("Are you sure you want to delete this test?")) return;
    try {
      const res = await fetch(`/api/tests/${id}`, {
        method: 'DELETE',
        headers: { 'Authorization': `Bearer ${user.accessToken}` }
      });
      if (res.ok) fetchTests();
    } catch (err) {
      console.error(err);
    }
  };

  const openAddModal = () => {
    setEditingId(null);
    setFormData({ testName: '', testCode: '', sampleType: 'Blood', price: '', categoryId: '', newCategoryName: '', summary: '' });
    setParameters([{ parameterName: '', referenceRange: '', unit: '', groupName: '', isQualitative: false }]);
    setIsModalOpen(true);
  };

  const openEditModal = (test) => {
    setEditingId(test.id);
    setFormData({
      testName: test.testName, testCode: test.testCode, sampleType: test.sampleType, price: test.price, categoryId: test.categoryId, newCategoryName: '', summary: test.summary || ''
    });
    setParameters(test.parameters?.length > 0 ? test.parameters : [{ parameterName: '', referenceRange: '', unit: '', groupName: '' }]);
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setEditingId(null);
  };

  const createWidalTestAuto = async () => {
    const existing = tests.find(t => t.testCode === 'WIDAL');
    if (existing) return alert('Widal test already exists!');
    try {
      let catId = categories.find(c => c.name === 'Immunology')?.id;
      if (!catId) {
        const catRes = await fetch('/api/tests/categories', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${user.accessToken}` },
          body: JSON.stringify({ name: 'Immunology' })
        });
        const catData = await catRes.json();
        catId = catData.id;
        fetchCategories();
      }
      const res = await fetch('/api/tests', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${user.accessToken}` },
        body: JSON.stringify({
          testName: 'WIDAL TEST (Rapid Slid Method)',
          testCode: 'WIDAL',
          sampleType: 'BLOOD',
          price: 200,
          categoryId: catId,
          summary: 'Widal test is a serological test for detecting antibodies against Salmonella typhi and paratyphi.',
          parameters: [
            { parameterName: 'S. TYPHI O', referenceRange: '', unit: '', groupName: '', isQualitative: true, titerValues: '1/20,1/40,1/80,1/160,1/320' },
            { parameterName: 'S. TYPHI H', referenceRange: '', unit: '', groupName: '', isQualitative: true, titerValues: '1/20,1/40,1/80,1/160,1/320' },
            { parameterName: 'S. PARA TYPHI A (H)', referenceRange: '', unit: '', groupName: '', isQualitative: true, titerValues: '1/20,1/40,1/80,1/160,1/320' },
            { parameterName: 'S. PARA TYPHI B (H)', referenceRange: '', unit: '', groupName: '', isQualitative: true, titerValues: '1/20,1/40,1/80,1/160,1/320' },
          ]
        })
      });
      if (res.ok) {
        alert('Widal test created successfully!');
        fetchTests();
      } else {
        alert('Failed to create Widal test');
      }
    } catch (err) {
      console.error(err);
      alert('Error creating Widal test');
    }
  };

  const createMantouxTestAuto = async () => {
    const existing = tests.find(t => t.testCode === 'MANTOUX-01');
    if (existing) {
      if (!window.confirm('Mantoux test already exists. Do you want to overwrite it with standard Mantoux parameters?')) return;
      try {
        await fetch(`/api/tests/${existing.id}`, {
          method: 'DELETE',
          headers: { 'Authorization': `Bearer ${user.accessToken}` }
        });
      } catch (err) {
        console.error(err);
      }
    }
    try {
      let catId = categories.find(c => c.name === 'Clinical Pathology')?.id;
      if (!catId) {
        const catRes = await fetch('/api/tests/categories', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${user.accessToken}` },
          body: JSON.stringify({ name: 'Clinical Pathology' })
        });
        const catData = await catRes.json();
        catId = catData.id;
        fetchCategories();
      }
      const res = await fetch('/api/tests', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${user.accessToken}` },
        body: JSON.stringify({
          testName: 'MANTOUX TEST (TUBERCULIN SKIN TEST)',
          testCode: 'MANTOUX-01',
          sampleType: 'Skin',
          price: 250,
          categoryId: catId,
          summary: 'Induration measuring 10 mm more is considered positive which shows hypersensitivity to tuberculoprotein. It indicates past or present infection with Mycobacterium tuberculosis.',
          parameters: [
            { parameterName: 'Tuberculin Dose', referenceRange: '0.1 mL of TU PPD', unit: '', groupName: 'MANTOUX TEST (Interdermal Skin Test)' },
            { parameterName: 'Induration (mm)', referenceRange: '', unit: 'mm', groupName: 'MANTOUX TEST (Interdermal Skin Test)' },
            { parameterName: 'Result after 48 hours', referenceRange: 'NEGATIVE / POSITIVE', unit: '', groupName: 'MANTOUX TEST (Interdermal Skin Test)', isQualitative: true },
          ]
        })
      });
      if (res.ok) {
        alert('Mantoux test created successfully!');
        fetchTests();
      } else {
        alert('Failed to create Mantoux test');
      }
    } catch (err) {
      console.error(err);
      alert('Error creating Mantoux test');
    }
  };

  const createMalariaTestAuto = async () => {
    const existing = tests.find(t => t.testCode === 'MALARIA-01');
    if (existing) {
      if (!window.confirm('Malaria test already exists. Do you want to overwrite it with standard Malaria parameters?')) return;
      try {
        await fetch(`/api/tests/${existing.id}`, {
          method: 'DELETE',
          headers: { 'Authorization': `Bearer ${user.accessToken}` }
        });
      } catch (err) {
        console.error(err);
      }
    }
    try {
      let catId = categories.find(c => c.name === 'Immunology & Serology' || c.name === 'Immunology')?.id;
      if (!catId) {
        const catRes = await fetch('/api/tests/categories', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${user.accessToken}` },
          body: JSON.stringify({ name: 'Immunology & Serology' })
        });
        const catData = await catRes.json();
        catId = catData.id;
        fetchCategories();
      }
      const res = await fetch('/api/tests', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${user.accessToken}` },
        body: JSON.stringify({
          testName: 'Malaria Micro (MP)',
          testCode: 'MP-MICRO',
          sampleType: 'Whole Blood',
          price: 150,
          categoryId: catId,
          summary: 'A Single negative smear does not rule out malaria. Test conducted on whole blood.',
          parameters: [
            { parameterName: 'Malaria Parasite', referenceRange: 'NOT-SEEN', unit: '', groupName: 'MALARIA PARASITE IDENTIFICATION (MICROSCOPY)', isQualitative: true },
          ]
        })
      });
      if (res.ok) {
        alert('Malaria test created successfully!');
        fetchTests();
      } else {
        alert('Failed to create Malaria test');
      }
    } catch (err) {
      console.error(err);
      alert('Error creating Malaria test');
    }
  };

  const filteredTests = tests.filter(t => 
    t.testName.toLowerCase().includes(searchTerm.toLowerCase()) || 
    t.testCode.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <Layout>
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-[#00488d] uppercase tracking-wide">Test Directory (Panels)</h2>
        <div className="flex gap-2">
          <button 
            onClick={createWidalTestAuto}
            className="bg-green-700 hover:bg-green-800 text-white px-4 py-2 rounded text-sm font-bold tracking-wide transition-colors flex items-center"
          >
            <Plus className="w-4 h-4 mr-2" /> CREATE WIDAL
          </button>
          <button 
            onClick={createMantouxTestAuto}
            className="bg-purple-700 hover:bg-purple-800 text-white px-4 py-2 rounded text-sm font-bold tracking-wide transition-colors flex items-center"
          >
            <Plus className="w-4 h-4 mr-2" /> CREATE MANTOUX
          </button>
          <button 
            onClick={createMalariaTestAuto}
            className="bg-indigo-700 hover:bg-indigo-800 text-white px-4 py-2 rounded text-sm font-bold tracking-wide transition-colors flex items-center"
          >
            <Plus className="w-4 h-4 mr-2" /> CREATE MALARIA
          </button>
          <button 
            onClick={openAddModal}
            className="bg-[#00488d] hover:bg-[#003875] text-white px-6 py-2 rounded text-sm font-bold tracking-wide transition-colors flex items-center"
          >
            <Plus className="w-4 h-4 mr-2" /> ADD TEST PANEL
          </button>
        </div>
      </div>

      <div className="bg-white rounded border border-gray-200 overflow-hidden shadow-sm">
        <div className="p-4 border-b border-gray-200 bg-gray-50 flex items-center">
          <div className="relative w-full max-w-md bg-white border border-gray-300 rounded flex items-center px-3 py-2 focus-within:border-[#00488d]">
            <Search className="w-4 h-4 text-gray-400 mr-2" />
            <input 
              type="text" 
              placeholder="Search by test name or code..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full text-sm focus:outline-none"
            />
          </div>
        </div>
        
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-gray-100 border-b border-gray-200">
                <th className="px-6 py-3 text-xs font-bold text-gray-700 uppercase">Test Name & Code</th>
                <th className="px-6 py-3 text-xs font-bold text-gray-700 uppercase">Category</th>
                <th className="px-6 py-3 text-xs font-bold text-gray-700 uppercase">Sample Type</th>
                <th className="px-6 py-3 text-xs font-bold text-gray-700 uppercase text-right">Price (₹)</th>
                <th className="px-6 py-3 text-xs font-bold text-gray-700 uppercase text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200">
              {filteredTests.length > 0 ? (
                filteredTests.map(t => (
                  <tr key={t.id} className="hover:bg-[#f2f7fc] transition-colors">
                    <td className="px-6 py-4">
                      {t.testCode === 'WIDAL' ? (
                        <p className="text-sm font-bold text-[#00488d] cursor-pointer hover:text-blue-700 flex items-center gap-1" onClick={() => navigate('/widal')}>
                          {t.testName} <ExternalLink className="w-3.5 h-3.5 inline opacity-50" />
                        </p>
                      ) : (
                        <p className="text-sm font-bold text-[#00488d]">{t.testName}</p>
                      )}
                      <p className="text-xs font-medium text-gray-500 font-mono mt-1">{t.testCode} • {t.parameters?.length || 0} Params</p>
                    </td>
                    <td className="px-6 py-4">
                      <span className="inline-flex items-center px-2 py-1 rounded text-xs font-bold bg-blue-50 text-[#00488d] border border-blue-100">
                        <Tag className="w-3 h-3 mr-1" /> {t.category?.name || 'Uncategorized'}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-700">{t.sampleType}</td>
                    <td className="px-6 py-4 text-right">
                      <span className="text-sm font-bold text-gray-900 bg-gray-100 px-3 py-1 rounded">
                        {t.price}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-sm text-right space-x-3">
                      <button onClick={() => openEditModal(t)} className="text-[#00488d] hover:text-blue-800" title="Edit">
                        <Edit2 className="w-4 h-4 inline-block" />
                      </button>
                      <button onClick={() => handleDelete(t.id)} className="text-red-500 hover:text-red-700" title="Delete">
                        <Trash2 className="w-4 h-4 inline-block" />
                      </button>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan="5" className="px-6 py-12 text-center text-gray-500 text-sm">
                    No tests found.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg shadow-xl w-full max-w-4xl overflow-hidden max-h-[90vh] flex flex-col">
            <div className="flex justify-between items-center p-6 border-b border-gray-200 shrink-0">
              <h3 className="text-xl font-bold text-[#00488d]">{editingId ? 'Edit Test Panel' : 'Add New Test Panel'}</h3>
              <button onClick={closeModal} className="text-gray-400 hover:text-gray-600">
                <X className="w-6 h-6" />
              </button>
            </div>
            <form onSubmit={handleSubmit} className="overflow-y-auto grow p-6">
              <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
                <div>
                  <label className="block text-sm font-bold text-gray-700 mb-1">Panel Name *</label>
                  <input type="text" required value={formData.testName} onChange={e => setFormData({...formData, testName: e.target.value})} className="w-full border border-gray-300 rounded px-3 py-2 focus:outline-none focus:border-[#00488d]" placeholder="e.g. C.B.C."/>
                </div>
                <div>
                  <label className="block text-sm font-bold text-gray-700 mb-1">Code *</label>
                  <input type="text" required value={formData.testCode} onChange={e => setFormData({...formData, testCode: e.target.value})} className="w-full border border-gray-300 rounded px-3 py-2 focus:outline-none focus:border-[#00488d]" />
                </div>
                <div>
                  <label className="block text-sm font-bold text-gray-700 mb-1">Price (₹) *</label>
                  <input type="number" required value={formData.price} onChange={e => setFormData({...formData, price: e.target.value})} className="w-full border border-gray-300 rounded px-3 py-2 focus:outline-none focus:border-[#00488d]" />
                </div>
                <div>
                  <label className="block text-sm font-bold text-gray-700 mb-1">Sample Type *</label>
                  <input type="text" required value={formData.sampleType} onChange={e => setFormData({...formData, sampleType: e.target.value})} className="w-full border border-gray-300 rounded px-3 py-2 focus:outline-none focus:border-[#00488d]" />
                </div>
                <div className="col-span-2">
                  <label className="block text-sm font-bold text-gray-700 mb-1">Category *</label>
                  <select value={formData.categoryId} onChange={e => setFormData({...formData, categoryId: e.target.value})} className="w-full border border-gray-300 rounded px-3 py-2 focus:outline-none focus:border-[#00488d]">
                    <option value="">Select or Create New...</option>
                    {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
                </div>
                {!formData.categoryId && (
                  <div className="col-span-2">
                    <label className="block text-sm font-bold text-gray-700 mb-1">New Category Name</label>
                    <input type="text" value={formData.newCategoryName} onChange={e => setFormData({...formData, newCategoryName: e.target.value})} className="w-full border border-gray-300 rounded px-3 py-2 focus:outline-none focus:border-[#00488d]" placeholder="e.g. Hematology" />
                  </div>
                )}
              </div>

              <div className="border border-gray-200 rounded p-4 bg-gray-50">
                  <div className="flex justify-between items-center mb-4">
                    <h4 className="font-bold text-[#00488d]">Test Parameters</h4>
                    <div className="flex gap-2">
                      <button type="button" onClick={fillWidalPreset} className="text-sm font-bold text-green-700 border border-green-600 px-3 py-1 rounded hover:bg-green-50">Quick Add Widal</button>
                      <button type="button" onClick={addParameterRow} className="text-sm font-bold text-[#00488d] border border-[#00488d] px-3 py-1 rounded hover:bg-blue-50">+ Add Row</button>
                    </div>
                  </div>
                <div className="space-y-2">
                  {parameters.map((p, idx) => (
                    <div key={idx} className="flex gap-2 items-start">
                      <input type="text" placeholder="Group Heading" value={p.groupName || ''} onChange={e => updateParameter(idx, 'groupName', e.target.value)} className="w-[15%] border border-gray-300 rounded px-2 py-1 text-sm focus:outline-none" />
                      <input type="text" placeholder="Parameter Name *" required value={p.parameterName} onChange={e => updateParameter(idx, 'parameterName', e.target.value)} className="w-[20%] border border-gray-300 rounded px-2 py-1 text-sm font-bold focus:outline-none" />
                      {p.isQualitative ? (
                        <>
                          <select
                            value={getQualitativeType(p)}
                            onChange={e => handleQualitativeTypeChange(idx, e.target.value)}
                            className="w-[15%] border border-gray-300 rounded px-2 py-1 text-sm focus:outline-none"
                          >
                            <option value="pos_neg">Positive / Negative</option>
                            <option value="reactive_nonreactive">Non-Reactive / Reactive</option>
                            <option value="seen_notseen">Not-Seen / Seen</option>
                            <option value="custom">Custom Options</option>
                            <option value="titer">Widal Titer Matrix</option>
                          </select>
                          {getQualitativeType(p) === 'custom' && (
                            <input
                              type="text"
                              placeholder="e.g. NEGATIVE / POSITIVE"
                              value={p.referenceRange || ''}
                              onChange={e => updateParameter(idx, 'referenceRange', e.target.value)}
                              className="w-[15%] border border-gray-300 rounded px-2 py-1 text-sm focus:outline-none font-bold"
                            />
                          )}
                          {getQualitativeType(p) === 'titer' && (
                            <input
                              type="text"
                              placeholder="Titers (e.g. 1/20,1/40)"
                              value={p.titerValues || ''}
                              onChange={e => updateParameter(idx, 'titerValues', e.target.value)}
                              className="w-[15%] border border-gray-300 rounded px-2 py-1 text-sm focus:outline-none font-bold"
                            />
                          )}
                          {(getQualitativeType(p) !== 'custom' && getQualitativeType(p) !== 'titer') && (
                            <div className="w-[15%] text-xs text-gray-500 italic pt-1.5 px-1 truncate">
                              {p.referenceRange}
                            </div>
                          )}
                        </>
                      ) : (
                        <>
                          <input type="text" placeholder="Reference Range" value={p.referenceRange || ''} onChange={e => updateParameter(idx, 'referenceRange', e.target.value)} className="w-[17%] border border-gray-300 rounded px-2 py-1 text-sm focus:outline-none" />
                          <input type="text" placeholder="Unit" value={p.unit || ''} onChange={e => updateParameter(idx, 'unit', e.target.value)} className="w-[13%] border border-gray-300 rounded px-2 py-1 text-sm focus:outline-none" />
                        </>
                      )}
                      <label className="flex items-center gap-1 text-[11px] font-bold text-gray-600 cursor-pointer whitespace-nowrap pt-1">
                        <input type="checkbox" checked={p.isQualitative} onChange={e => handleIsQualitativeToggle(idx, e.target.checked)} className="accent-[#00488d]" />
                        Qualitative?
                      </label>
                      <button type="button" onClick={() => removeParameterRow(idx)} className="text-red-500 p-1 hover:bg-red-100 rounded shrink-0 mt-1"><Trash2 className="w-4 h-4" /></button>
                    </div>
                  ))}
                </div>
              </div>

              {/* Summary / Clinical Notes */}
              <div className="mt-4">
                <label className="block text-sm font-bold text-gray-700 mb-1">
                  Summary / Clinical Notes <span className="text-gray-400 font-normal">(appears on report under this test)</span>
                </label>
                <textarea value={formData.summary} onChange={e => setFormData({...formData, summary: e.target.value})} rows="4" className="w-full border border-gray-300 rounded px-3 py-2 text-sm focus:outline-none focus:border-[#00488d]" placeholder="Optional: Add clinical notes, interpretations, or references to display on the report..."></textarea>
              </div>

              <div className="mt-8 flex justify-end space-x-4">
                <button type="button" onClick={closeModal} className="px-6 py-2 border border-gray-300 rounded text-gray-700 font-bold hover:bg-gray-50">Cancel</button>
                <button type="submit" className="px-6 py-2 bg-[#00488d] text-white rounded font-bold hover:bg-[#003875]">{editingId ? 'Update Panel' : 'Save Panel'}</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default Tests;

import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import PublicLayout from '../components/PublicLayout';
import { TESTS_DATA, HEALTH_PACKAGES_DATA } from '../data/testsData';
import { Search, Info, Plus, Check, ShoppingCart } from 'lucide-react';
import PackageCard from '../components/PackageCard';
import PackageDetailsModal from '../components/PackageDetailsModal';

const TestsCatalog = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [search, setSearch] = useState(() => {
    const params = new URLSearchParams(location.search);
    return params.get('q') || '';
  });
  const [activeCategory, setActiveCategory] = useState('All');
  const [selectedPackageDetails, setSelectedPackageDetails] = useState(null);
  const [cart, setCart] = useState(() => {
    try {
      const saved = localStorage.getItem('sana_cart');
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  useEffect(() => {
    localStorage.setItem('sana_cart', JSON.stringify(cart));
  }, [cart]);

  // Extract unique categories
  const categories = ['All', ...new Set(TESTS_DATA.map(t => t.category?.name || 'Other'))];

  // Filter tests
  const filteredTests = TESTS_DATA.filter(t => {
    const matchesSearch = t.testName.toLowerCase().includes(search.toLowerCase()) || 
                          t.code.toLowerCase().includes(search.toLowerCase());
    const matchesCategory = activeCategory === 'All' || (t.category?.name === activeCategory);
    return matchesSearch && matchesCategory;
  });

  const toggleCartItem = (test, isPackage = false) => {
    const itemKey = test.code;
    const exists = cart.some(item => item.testCode === itemKey);
    
    if (exists) {
      setCart(prev => prev.filter(item => item.testCode !== itemKey));
    } else {
      const newItem = {
        id: test.id || Date.now(),
        testCode: itemKey,
        name: test.testName || test.name,
        price: test.price,
        sampleType: test.sampleType || 'Blood',
        category: isPackage ? 'Package' : 'Catalog'
      };
      setCart(prev => [...prev, newItem]);
    }
  };

  const handleBookNow = (pkg) => {
    if (!isInCart(pkg.code)) {
      setCart(prev => [...prev, {
        id: pkg.id || Date.now(),
        testCode: pkg.code,
        name: pkg.name,
        price: pkg.price,
        sampleType: pkg.sampleType || 'Blood',
        category: 'Package'
      }]);
    }
    navigate('/book-online');
    window.scrollTo(0, 0);
  };

  const isInCart = (code) => {
    return cart.some(item => item.testCode === code);
  };

  return (
    <PublicLayout>
      <div className="bg-[#F5F7F6] min-h-screen py-10">
        <div className="max-w-7xl mx-auto px-4">
          
          {/* Header Banner */}
          <div className="text-center max-w-3xl mx-auto mb-10 space-y-4">
            <span className="bg-[#1D9E75]/10 text-[#1D9E75] text-xs font-black uppercase px-4 py-1.5 rounded-full border border-[#1D9E75]/20 tracking-wider inline-block">
              NABL Standard Pathology Tests
            </span>
            <h1 className="text-3xl md:text-5xl font-black font-heading text-[#085041] tracking-tight leading-none">
              Interactive Test Directory
            </h1>
            <p className="text-slate-600 text-sm md:text-base leading-relaxed">
              Browse our complete catalog of pathology tests and wellness packages. Select the tests you need to configure your home collection booking.
            </p>
          </div>

          {/* Search and Category Filters */}
          <div className="bg-white rounded-3xl p-6 border border-slate-100 shadow-xl mb-8 space-y-6">
            <div className="relative group max-w-2xl mx-auto">
              <div className="absolute -inset-0.5 bg-gradient-to-r from-[#1D9E75]/20 to-emerald-300/20 rounded-2xl blur opacity-0 group-focus-within:opacity-100 transition-opacity duration-300 pointer-events-none"></div>
              <input
                type="text"
                placeholder="Search for blood tests, sugar, lipid, thyroid, packages..."
                value={search}
                onChange={e => setSearch(e.target.value)}
                className="relative w-full pl-12 pr-5 py-4 border-2 border-slate-200 rounded-2xl text-sm font-semibold focus:outline-none focus:border-[#1D9E75] transition-all bg-white/80"
              />
              <Search className="w-5 h-5 text-slate-400 absolute left-4 top-4.5" />
            </div>

            {/* Category Pills */}
            <div className="flex flex-wrap items-center justify-center gap-2">
              {categories.map(cat => (
                <button
                  key={cat}
                  onClick={() => setActiveCategory(cat)}
                  className={`px-5 py-2.5 rounded-full text-xs font-black transition-all ${
                    activeCategory === cat
                      ? 'bg-[#1D9E75] text-white shadow-md'
                      : 'bg-[#F5F7F6] text-slate-500 hover:bg-slate-200/60 hover:text-slate-700'
                  }`}
                >
                  {cat}
                </button>
              ))}
            </div>
          </div>

          <div className="mb-12">
            <h2 className="text-2xl font-black text-[#085041] mb-6 font-heading">Suggested Health Packages</h2>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
              {HEALTH_PACKAGES_DATA.slice(0, 4).map(pkg => (
                <PackageCard 
                  key={pkg.code} 
                  pkg={pkg} 
                  isAdded={isInCart(pkg.code)}
                  onAdd={() => toggleCartItem(pkg, true)}
                  onKnowMore={(p) => setSelectedPackageDetails(p)}
                  onBookNow={handleBookNow}
                  onWhatsApp={(msg) => window.open(`https://wa.me/916396786939?text=${encodeURIComponent(msg)}`, '_blank')}
                />
              ))}
            </div>
          </div>

          {/* Test List Section */}
          <div>
            <h2 className="text-2xl font-black text-[#085041] mb-6 font-heading">Pathology Test Catalog ({filteredTests.length})</h2>
            <div className="bg-white rounded-3xl border border-slate-100 shadow-xl overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                  <thead>
                    <tr className="bg-slate-50 border-b border-slate-100 text-xs font-black text-slate-500 uppercase tracking-wider">
                      <th className="py-4 px-6">Test Detail</th>
                      <th className="py-4 px-6">Prep / Instruction</th>
                      <th className="py-4 px-6">Sample</th>
                      <th className="py-4 px-6 text-right">Price</th>
                      <th className="py-4 px-6 text-center">Action</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {filteredTests.map(t => {
                      const selected = isInCart(t.code);
                      return (
                        <tr key={t.code} className="hover:bg-slate-50/40 transition-colors">
                          <td className="py-4 px-6">
                            <p className="font-extrabold text-slate-800 text-sm">{t.testName}</p>
                            <p className="text-[10px] text-slate-400 font-bold uppercase mt-0.5">Code: {t.code} | {t.category?.name}</p>
                          </td>
                          <td className="py-4 px-6 text-xs text-slate-500">
                            <span className="flex items-start gap-1">
                              <Info size={14} className="text-slate-400 shrink-0 mt-0.5" />
                              <span>{t.preparation || 'No special preparation needed.'}</span>
                            </span>
                          </td>
                          <td className="py-4 px-6 text-xs font-bold text-slate-600">{t.sampleType}</td>
                          <td className="py-4 px-6 text-right font-black text-base text-[#1D9E75]">₹{t.price}</td>
                          <td className="py-4 px-6 text-center">
                            <button
                              onClick={() => toggleCartItem(t, false)}
                              className={`p-2.5 rounded-xl transition-all ${
                                selected
                                  ? 'bg-emerald-50 text-emerald-700 border border-emerald-200'
                                  : 'bg-[#1D9E75]/10 text-[#1D9E75] hover:bg-[#1D9E75]/20'
                              }`}
                              title={selected ? 'Remove from Booking' : 'Add to Booking'}
                            >
                              {selected ? <Check size={16} /> : <Plus size={16} />}
                            </button>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>
          </div>

          {/* Floating Cart Button */}
          {cart.length > 0 && (
            <div className="fixed bottom-6 right-24 z-50">
              <button
                onClick={() => navigate('/#booking')}
                className="flex items-center gap-2 bg-[#BA7517] hover:bg-[#9E6312] text-white px-6 py-4 rounded-full shadow-2xl transition-transform hover:scale-105 active:scale-95 font-extrabold text-sm"
              >
                <ShoppingCart size={18} />
                <span>Book Selected ({cart.length})</span>
              </button>
            </div>
          )}

        </div>
      </div>
      
      <PackageDetailsModal 
        pkg={selectedPackageDetails}
        onClose={() => setSelectedPackageDetails(null)}
        onBookNow={(p) => {
          setSelectedPackageDetails(null);
          handleBookNow(p);
        }}
        isAdded={selectedPackageDetails ? isInCart(selectedPackageDetails.code) : false}
      />
    </PublicLayout>
  );
};

export default TestsCatalog;

import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import {
  Search, FileText, Calendar, Phone, MapPin, User, Clock,
  ArrowRight, ChevronRight, ExternalLink, CheckCircle2, AlertCircle, Loader2
} from 'lucide-react';
import PublicLayout from '../components/PublicLayout';

const API = '/api';

const STATUS_BADGES = {
  COMPLETED: { label: 'Ready', class: 'bg-emerald-100 text-emerald-700 border-emerald-200' },
  PROCESSING: { label: 'Processing', class: 'bg-amber-100 text-amber-700 border-amber-200' },
  PENDING: { label: 'Pending', class: 'bg-slate-100 text-slate-600 border-slate-200' },
  CONFIRMED: { label: 'Confirmed', class: 'bg-blue-100 text-blue-700 border-blue-200' },
  CANCELLED: { label: 'Cancelled', class: 'bg-red-100 text-red-600 border-red-200' },
};

const StatusBadge = ({ status }) => {
  const s = STATUS_BADGES[status] || { label: status || 'Unknown', class: 'bg-slate-100 text-slate-600 border-slate-200' };
  return (
    <span className={`text-[11px] font-bold px-3 py-1 rounded-full border whitespace-nowrap ${s.class}`}>
      {s.label}
    </span>
  );
};

const initialState = {
  query: '',
  results: null,
  error: '',
  loading: false,
};

const Track = () => {
  const [activeTab, setActiveTab] = useState('report');
  const [searchMethod, setSearchMethod] = useState('mobile');

  const [report, setReport] = useState({ ...initialState });
  const [booking, setBooking] = useState({ ...initialState });

  const trackGA4 = (action, label) => {
    if (window.gtag) {
      window.gtag('event', action, { event_label: label });
    }
  };

  const handleReportSearch = async (e) => {
    e.preventDefault();
    if (!report.query.trim()) return;

    setReport(prev => ({ ...prev, loading: true, error: '', results: null }));
    trackGA4('search', `report_${searchMethod}`);

    try {
      const param = searchMethod === 'mobile' ? 'mobile' : 'reportNumber';
      const res = await fetch(`${API}/public/report-lookup?${param}=${encodeURIComponent(report.query.trim())}`);
      const data = await res.json();
      if (!res.ok) {
        setReport(prev => ({ ...prev, error: data.message || 'No reports found.', loading: false }));
      } else {
        setReport(prev => ({ ...prev, results: Array.isArray(data) ? data : [data], loading: false }));
      }
    } catch {
      setReport(prev => ({ ...prev, error: 'Failed to connect. Please try again.', loading: false }));
    }
  };

  const handleBookingSearch = async (e) => {
    e.preventDefault();
    if (!booking.query.trim()) return;

    setBooking(prev => ({ ...prev, loading: true, error: '', results: null }));
    trackGA4('search', 'booking_mobile');

    try {
      const res = await fetch(`${API}/public/appointment-lookup?mobile=${encodeURIComponent(booking.query.trim())}`);
      const data = await res.json();
      if (!res.ok) {
        setBooking(prev => ({ ...prev, error: data.message || 'No bookings found.', loading: false }));
      } else {
        setBooking(prev => ({ ...prev, results: Array.isArray(data) ? data : [data], loading: false }));
      }
    } catch {
      setBooking(prev => ({ ...prev, error: 'Failed to connect. Please try again.', loading: false }));
    }
  };

  return (
    <PublicLayout>
      {/* Hero Banner */}
      <section className="bg-gradient-to-r from-[#085041] to-[#0F6E56] text-white py-14 md:py-20">
        <div className="max-w-4xl mx-auto px-4 text-center">
          <h1 className="text-3xl md:text-5xl font-heading font-bold mb-4 leading-tight">
            Track Your Report or Booking
          </h1>
          <p className="text-sm md:text-base text-[#A7D8CB] max-w-xl mx-auto mb-6 flex items-center justify-center gap-2">
            <CheckCircle2 className="w-4 h-4 text-[#1D9E75] shrink-0" />
            Apna report yahan check karein. Ya apni booking ka status dekhein.
          </p>
          <span className="inline-block bg-white/10 text-[#A7D8CB] text-xs font-bold px-4 py-2 rounded-full border border-white/20">
            Fast &bull; Secure &bull; 24/7 Access
          </span>
        </div>
      </section>

      {/* Card with Tabs */}
      <section className="max-w-4xl mx-auto px-4 -mt-8 pb-12 relative z-10">
        <div className="bg-white rounded-2xl shadow-xl border border-slate-100 overflow-hidden">
          {/* Tabs */}
          <div className="flex border-b border-slate-200">
            <button
              onClick={() => { setActiveTab('report'); setReport({ ...initialState }); }}
              className={`flex-1 flex items-center justify-center gap-2 py-4 text-sm font-bold transition-all ${
                activeTab === 'report'
                  ? 'text-[#1D9E75] border-b-2 border-[#1D9E75] bg-[#E1F5EE]/30'
                  : 'text-slate-500 hover:text-slate-700 hover:bg-slate-50'
              }`}
            >
              &#x1F52C; Track Report
            </button>
            <button
              onClick={() => { setActiveTab('booking'); setBooking({ ...initialState }); }}
              className={`flex-1 flex items-center justify-center gap-2 py-4 text-sm font-bold transition-all ${
                activeTab === 'booking'
                  ? 'text-[#1D9E75] border-b-2 border-[#1D9E75] bg-[#E1F5EE]/30'
                  : 'text-slate-500 hover:text-slate-700 hover:bg-slate-50'
              }`}
            >
              &#x1F4CB; Track Booking
            </button>
          </div>

          <div className="p-5 md:p-8">

            {/* ─── TAB 1: TRACK REPORT ─── */}
            {activeTab === 'report' && (
              <div>
                {/* Radio Options */}
                <div className="flex flex-wrap gap-4 mb-6">
                  {['mobile', 'reportNumber'].map((m) => (
                    <label key={m} className="flex items-center gap-2 cursor-pointer">
                      <input
                        type="radio"
                        name="searchMethod"
                        checked={searchMethod === m}
                        onChange={() => { setSearchMethod(m); setReport({ ...initialState }); }}
                        className="w-4 h-4 text-[#1D9E75] focus:ring-[#1D9E75]"
                      />
                      <span className="text-sm font-semibold text-slate-700">
                        By {m === 'mobile' ? 'Mobile Number' : 'Report Number'}
                      </span>
                    </label>
                  ))}
                </div>

                {/* Search Form */}
                <form onSubmit={handleReportSearch} className="flex flex-col sm:flex-row gap-3 mb-6">
                  <div className="flex-1 relative">
                    {searchMethod === 'mobile' ? (
                      <input
                        type="tel"
                        value={report.query}
                        onChange={e => setReport(prev => ({ ...prev, query: e.target.value.replace(/\D/g, '').slice(0, 10) }))}
                        placeholder="Enter 10-digit mobile number"
                        className="w-full px-4 py-3.5 border-2 border-slate-200 rounded-xl text-sm font-semibold focus:outline-none focus:border-[#1D9E75] focus:ring-2 focus:ring-[#1D9E75]/10 transition-all"
                        required
                        pattern="[0-9]{10}"
                        maxLength={10}
                        inputMode="numeric"
                      />
                    ) : (
                      <input
                        type="text"
                        value={report.query}
                        onChange={e => setReport(prev => ({ ...prev, query: e.target.value }))}
                        placeholder="Enter report number (e.g. SPL-001)"
                        className="w-full px-4 py-3.5 border-2 border-slate-200 rounded-xl text-sm font-semibold focus:outline-none focus:border-[#1D9E75] focus:ring-2 focus:ring-[#1D9E75]/10 transition-all"
                        required
                      />
                    )}
                  </div>
                  <button
                    type="submit"
                    disabled={report.loading}
                    className="bg-[#1D9E75] hover:bg-[#1D9E75]/90 text-white px-8 py-3.5 rounded-xl font-bold text-sm transition-all active:scale-[0.98] disabled:opacity-60 flex items-center justify-center gap-2 shadow-lg shadow-[#1D9E75]/20"
                  >
                    {report.loading ? (
                      <Loader2 className="w-4 h-4 animate-spin" />
                    ) : (
                      <Search className="w-4 h-4" />
                    )}
                    {report.loading ? 'Searching...' : 'Search'}
                  </button>
                </form>

                {/* Error State */}
                {report.error && (
                  <div className="flex items-center gap-3 bg-red-50 text-red-700 border border-red-200 rounded-xl px-5 py-4 mb-6 animate-fade-in-up">
                    <AlertCircle className="w-5 h-5 shrink-0" />
                    <p className="text-sm font-semibold">{report.error}</p>
                  </div>
                )}

                {/* Results */}
                {report.results && report.results.length > 0 && (
                  <div className="space-y-3 animate-fade-in-up">
                    <p className="text-sm font-bold text-slate-500 mb-3">
                      {report.results.length} report{report.results.length > 1 ? 's' : ''} found
                    </p>
                    {report.results.map((item, idx) => (
                      <div
                        key={item.id || idx}
                        className="border border-slate-200 rounded-xl p-4 hover:shadow-md transition-shadow bg-white"
                        style={{ animationDelay: `${idx * 0.08}s` }}
                      >
                        <div className="flex items-start justify-between gap-4">
                          <div className="min-w-0 flex-1">
                            <h4 className="font-bold text-slate-800 text-sm mb-1">
                              {item.testName || item.patient?.fullName || 'Lab Report'}
                            </h4>
                            {item.reportDate && (
                              <span className="flex items-center gap-1 text-xs text-slate-500">
                                <Calendar className="w-3.5 h-3.5 text-slate-400" />
                                {new Date(item.reportDate).toLocaleDateString('en-IN', {
                                  day: 'numeric', month: 'short', year: 'numeric'
                                })}
                              </span>
                            )}
                          </div>
                          <StatusBadge status={item.status} />
                        </div>
                        {item.status === 'COMPLETED' && (
                          <div className="mt-3 pt-3 border-t border-slate-100">
                            <Link
                              to={`/report-lookup#?reportNumber=${encodeURIComponent(item.reportNumber || '')}&patientName=${encodeURIComponent(item.patient?.fullName || '')}`}
                              className="inline-flex items-center gap-1.5 text-[#1D9E75] text-xs font-bold hover:underline group"
                            >
                              View Report
                              <ExternalLink className="w-3.5 h-3.5 group-hover:translate-x-0.5 transition-transform" />
                            </Link>
                          </div>
                        )}
                      </div>
                    ))}
                  </div>
                )}

                {/* Empty Results */}
                {report.results && report.results.length === 0 && !report.error && (
                  <div className="text-center py-12 animate-fade-in-up">
                    <FileText className="w-12 h-12 text-slate-300 mx-auto mb-4" />
                    <p className="text-slate-500 font-semibold">No reports found</p>
                    <p className="text-xs text-slate-400 mt-1">Try a different search method or check your details.</p>
                  </div>
                )}

                {/* Initial Prompt */}
                {!report.results && !report.error && !report.loading && (
                  <div className="text-center py-12">
                    <Search className="w-12 h-12 text-slate-300 mx-auto mb-4" />
                    <p className="text-slate-400 text-sm">Enter your mobile number or report number to search</p>
                  </div>
                )}
              </div>
            )}

            {/* ─── TAB 2: TRACK BOOKING ─── */}
            {activeTab === 'booking' && (
              <div>
                <form onSubmit={handleBookingSearch} className="flex flex-col sm:flex-row gap-3 mb-6">
                  <div className="flex-1">
                    <input
                      type="tel"
                      value={booking.query}
                      onChange={e => setBooking(prev => ({ ...prev, query: e.target.value.replace(/\D/g, '').slice(0, 10) }))}
                      placeholder="Enter registered mobile number"
                      className="w-full px-4 py-3.5 border-2 border-slate-200 rounded-xl text-sm font-semibold focus:outline-none focus:border-[#1D9E75] focus:ring-2 focus:ring-[#1D9E75]/10 transition-all"
                      required
                      pattern="[0-9]{10}"
                      maxLength={10}
                      inputMode="numeric"
                    />
                  </div>
                  <button
                    type="submit"
                    disabled={booking.loading}
                    className="bg-[#1D9E75] hover:bg-[#1D9E75]/90 text-white px-8 py-3.5 rounded-xl font-bold text-sm transition-all active:scale-[0.98] disabled:opacity-60 flex items-center justify-center gap-2 shadow-lg shadow-[#1D9E75]/20"
                  >
                    {booking.loading ? (
                      <Loader2 className="w-4 h-4 animate-spin" />
                    ) : (
                      <Search className="w-4 h-4" />
                    )}
                    {booking.loading ? 'Searching...' : 'Search'}
                  </button>
                </form>

                {/* Error */}
                {booking.error && (
                  <div className="flex items-center gap-3 bg-red-50 text-red-700 border border-red-200 rounded-xl px-5 py-4 mb-6 animate-fade-in-up">
                    <AlertCircle className="w-5 h-5 shrink-0" />
                    <p className="text-sm font-semibold">{booking.error}</p>
                  </div>
                )}

                {/* Booking Results */}
                {booking.results && booking.results.length > 0 && (
                  <div className="space-y-4 animate-fade-in-up">
                    <p className="text-sm font-bold text-slate-500 mb-3">
                      {booking.results.length} booking{booking.results.length > 1 ? 's' : ''} found
                    </p>
                    {booking.results.map((b, idx) => (
                      <div
                        key={b.id || idx}
                        className="border border-slate-200 rounded-xl p-4 hover:shadow-md transition-shadow bg-white"
                        style={{ animationDelay: `${idx * 0.08}s` }}
                      >
                        <div className="flex items-start justify-between gap-4 mb-3">
                          <div className="min-w-0 flex-1">
                            <h4 className="font-bold text-slate-800 text-sm mb-1 flex items-center gap-2">
                              <User className="w-4 h-4 text-[#1D9E75] shrink-0" />
                              {b.patientName || b.name || 'Patient'}
                            </h4>
                            <div className="flex flex-wrap gap-x-4 gap-y-1.5 text-xs text-slate-500">
                              {b.date && (
                                <span className="flex items-center gap-1">
                                  <Calendar className="w-3.5 h-3.5 text-slate-400" />
                                  {new Date(b.date).toLocaleDateString('en-IN', {
                                    day: 'numeric', month: 'short', year: 'numeric'
                                  })}
                                </span>
                              )}
                              {b.time && (
                                <span className="flex items-center gap-1">
                                  <Clock className="w-3.5 h-3.5 text-slate-400" />
                                  {b.time}
                                </span>
                              )}
                            </div>
                          </div>
                          <StatusBadge status={b.status} />
                        </div>

                        {b.address && (
                          <p className="flex items-start gap-1.5 text-xs text-slate-500 mb-3">
                            <MapPin className="w-3.5 h-3.5 text-slate-400 shrink-0 mt-0.5" />
                            {b.address}
                          </p>
                        )}

                        {b.tests && b.tests.length > 0 && (
                          <div className="mb-3">
                            <p className="text-xs font-bold text-slate-600 mb-1.5">Tests:</p>
                            <div className="flex flex-wrap gap-1.5">
                              {b.tests.map((test, i) => (
                                <span
                                  key={i}
                                  className="text-xs bg-slate-100 text-slate-600 px-2.5 py-1 rounded-full font-medium"
                                >
                                  {test.name || test}
                                </span>
                              ))}
                            </div>
                          </div>
                        )}

                        <div className="pt-3 border-t border-slate-100">
                          <Link
                            to={`/track/${b.id}`}
                            className="inline-flex items-center gap-1 text-[#1D9E75] text-xs font-bold hover:underline group"
                          >
                            Track Phlebotomist
                            <ChevronRight className="w-3.5 h-3.5 group-hover:translate-x-0.5 transition-transform" />
                          </Link>
                        </div>
                      </div>
                    ))}
                  </div>
                )}

                {/* Empty */}
                {booking.results && booking.results.length === 0 && !booking.error && (
                  <div className="text-center py-12 animate-fade-in-up">
                    <Calendar className="w-12 h-12 text-slate-300 mx-auto mb-4" />
                    <p className="text-slate-500 font-semibold">No bookings found</p>
                    <p className="text-xs text-slate-400 mt-1">Enter the mobile number used at the time of booking.</p>
                  </div>
                )}

                {/* Initial */}
                {!booking.results && !booking.error && !booking.loading && (
                  <div className="text-center py-12">
                    <Search className="w-12 h-12 text-slate-300 mx-auto mb-4" />
                    <p className="text-slate-400 text-sm">Enter your mobile number to check booking status</p>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>

        {/* Need Help */}
        <div className="mt-8 bg-white rounded-2xl shadow-xl border border-slate-100 p-6 md:p-8 text-center">
          <h3 className="text-lg font-bold text-slate-800 mb-5">Need Help?</h3>
